-- =====================================================================
-- 096 — Perfil completo + farmacologia de 30 fármacos (lote 5, final)
-- ---------------------------------------------------------------------
-- Perfis (drug_profiles, padrão 090) E farmacologia (drug_pharmacology,
-- padrão 088/091/092) dos últimos 30 fármacos sem perfil (0 pares na
-- BD, confirmado por consulta read-only). Com esta migração, os 182
-- fármacos ativos ficam todos com perfil + farmacologia.
-- Fontes (citadas por linha):
--   • 27 fármacos: secções INDICATIONS AND USAGE, ADVERSE REACTIONS,
--     CONTRAINDICATIONS, WARNINGS AND PRECAUTIONS + secção 12 CLINICAL
--     PHARMACOLOGY dos rótulos aprovados DailyMed (setIDs validados);
--   • artesunato: SmPC-padrão WHO-prequalificado (MA152; artesunato
--     t½ 3–29 min; DHA 40–95 min) — sem rótulo DailyMed nos EUA;
--   • butilbrometo_hioscina: SmPC Buscopan (EMC-UK, product 1775) —
--     composto de amónio quaternário, absorção oral ~8%;
--   • etilefrina: Hengstmann 1975 (PMID 9300) — bio ~55%, t½ ~2 h.
-- Conteúdo autoral (não copiado), ancorado nos números das fontes.
-- Idempotente: ON CONFLICT (drug_id) DO NOTHING — reaplicar é seguro.
-- Padrão 7.6 (JOIN ON d.slug = v.slug). Aplicar na ordem 079 → 096.
-- =====================================================================

-- =====================================================================
-- Perfis (drug_profiles)
-- =====================================================================

INSERT INTO public.drug_profiles
  (drug_id, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
   indications_pt, indications_en, side_effects_pt, side_effects_en,
   precautions_pt, precautions_en, source_pt, source_en)
SELECT d.id, v.overview_public_pt, v.overview_public_en, v.overview_pro_pt, v.overview_pro_en,
       v.indications_pt, v.indications_en, v.side_effects_pt, v.side_effects_en,
       v.precautions_pt, v.precautions_en, v.source_pt, v.source_en
FROM (VALUES
-- ---------------------------------------------------------------------
-- Perfis — B1 (acetilcisteina, ácido ursodesoxicolico, artesunato,
-- benzilpenicilina benzatina, butilbrometo de hioscina)
-- ---------------------------------------------------------------------
  ('acetilcisteina',
   E'Adjuvante no tratamento de doentes com secreções mucosas anormais, viscosas ou espessas, em doenças broncopulmonares crónicas (enfisema, bronquite, asma brônquica, tuberculose, bronquiectasias), agudas (pneumonia, bronquite, traqueobronquite), fibrose quística, cuidados pós-traqueostomia, complicações pulmonares pós-cirúrgicas, atelectasia por obstrução mucosa e estudos broncoscópicos diagnósticos.',
   E'Adjuvant therapy for patients with abnormal, viscid, or inspissated mucous secretions in chronic bronchopulmonary disease, acute bronchopulmonary disease, pulmonary complications of cystic fibrosis, tracheostomy care, pulmonary complications associated with surgery, and atelectasis due to mucous obstruction.',
   E'Adjuvante da terapêutica de secreções mucosas anormais ou viscosas em doença broncopulmonar crónica e aguda, fibrose quística, cuidados pós-traqueostomia e complicações pulmonares pós-cirúrgicas. O efeito mucolítico resulta da quebra das pontes dissulfureto das glicoproteínas do muco, reduzindo a sua viscosidade e facilitando a expetoração.',
   E'Adjuvant for abnormal or viscid mucous secretions in chronic and acute bronchopulmonary disease, cystic fibrosis, tracheostomy care and post-surgical pulmonary complications. The mucolytic effect results from cleavage of disulfide bonds in mucus glycoproteins, reducing viscosity and facilitating expectoration.',
   E'• Doença broncopulmonar crónica (enfisema, bronquite crónica asmática, tuberculose, bronquiectasias)\n• Doença broncopulmonar aguda (pneumonia, bronquite, traqueobronquite)\n• Fibrose quística\n• Cuidados pós-traqueostomia\n• Atelectasia por obstrução mucosa\n• Estudos broncoscópicos diagnósticos',
   E'• Chronic bronchopulmonary disease (emphysema, chronic asthmatic bronchitis, tuberculosis, bronchiectasis)\n• Acute bronchopulmonary disease (pneumonia, bronchitis, tracheobronchitis)\n• Pulmonary complications of cystic fibrosis\n• Tracheostomy care\n• Atelectasis due to mucous obstruction\n• Diagnostic bronchial studies',
   E'• Estomatite, náuseas, vómitos e febre\n• Rinorreia, sonolência, sensação de humidade e aperto torácico\n• Broncoconstrição (broncospasmo induzido clinicamente evidente é pouco frequente e imprevisível, mesmo em doentes com bronquite asmática)\n• Sensibilização (rara; erupções cutâneas em terapeutas inalatórios com exposição frequente e prolongada)\n• Irritação traqueobrônquica e, raramente, hemoptise',
   E'• Stomatitis, nausea, vomiting, fever, rhinorrhea, drowsiness, clamminess, chest tightness\n• Bronchoconstriction (clinically overt induced bronchospasm is infrequent and unpredictable, even in asthmatic bronchitis)\n• Acquired sensitization reported rarely; confirmed in inhalation therapists with frequent, extended exposure\n• Irritation of the tracheal and bronchial tracts; hemoptysis has occurred',
   E'• Manter a via aérea desobstruída quando o aumento do volume de secreções liquefeitas ultrapassa a capacidade de tosse (aspiração mecânica)\n• Vigiar broncospasmo em doentes com asma ou bronquite asmática; suspender se ocorrer reação de hipersensibilidade\n• Descartar corpo estranho ou acumulação local quando há bloqueio mecânico',
   E'• Maintain an open airway when the increased volume of liquified secretions exceeds cough capacity (mechanical suction)\n• Monitor for bronchospasm in patients with asthma or asthmatic bronchitis; discontinue if hypersensitivity occurs\n• Rule out foreign body or local accumulation when there is mechanical airway block',
   'Rótulo aprovado DailyMed (Acetylcysteine Solution, Hospira; setID 5558a5f5-e821-473b-7d8a-5d33d09f0586).',
   'DailyMed approved label (Acetylcysteine Solution, Hospira; setID 5558a5f5-e821-473b-7d8a-5d33d09f0586).'),
  ('acido_ursodesoxicolico',
   E'Dissolução de cálculos biliares de colesterol radiotransparentes, não calcificados, com menos de 20 mm de diâmetro, em doentes com risco cirúrgico aumentado; prevenção da formação de cálculos biliares em doentes obesos com perda de peso rápida.',
   E'Dissolution of radiolucent, noncalcified cholesterol gallbladder stones < 20 mm in greatest diameter in patients at increased surgical risk; prevention of gallstone formation in obese patients experiencing rapid weight loss.',
   E'Ácido biliar hidrofílico que reduz a saturação de colesterol da bílis, diminuindo a absorção intestinal e a secreção hepática de colesterol e formando uma fase líquida-cristalina que dissolverá lentamente os cálculos de colesterol. Indicado também na prevenção de litíase em doentes obesos em perda rápida de peso.',
   E'Hydrophilic bile acid that reduces biliary cholesterol saturation by decreasing intestinal absorption and hepatic secretion of cholesterol, forming a liquid-crystalline phase that slowly dissolves cholesterol gallstones. Also indicated for gallstone prevention in obese patients with rapid weight loss.',
   E'• Cálculos biliares de colesterol radiotransparentes, não calcificados, < 20 mm, quando a colecistectomia eletiva acarreta risco cirúrgico aumentado (doença sistémica, idade avançada, reação idiossincrática à anestesia geral) ou recusa de cirurgia\n• Prevenção de cálculos biliares em obesos com perda de peso rápida',
   E'• Radiolucent, noncalcified cholesterol gallstones < 20 mm in patients in whom elective cholecystectomy would carry increased surgical risk or who refuse surgery\n• Prevention of gallstone formation in obese patients with rapid weight loss',
   E'• Diarreia e fezes moles (o mais frequente)\n• Dor abdominal, obstipação, náuseas, vómitos\n• Reações alérgicas e prurido (pouco frequentes)\n• Litíase biliar calcificada (radiológica) com terapia prolongada',
   E'• Diarrhea and loose stools (most common)\n• Abdominal pain, constipation, nausea, vomiting\n• Allergic reactions and pruritus (infrequent)\n• Calcified gallstones with prolonged therapy',
   E'• Não utilizar em cálculos calcificados, radiopacos ou pigmentares, nem em colecistite aguda, colangite, obstrução biliar, pancreatite biliar ou fístula biliar-gastrointestinal\n• Segurança além de 24 meses de uso não estabelecida\n• Avaliar a dissolução por ecografia/colecistografia durante o tratamento',
   E'• Do not use for calcified, radiopaque or pigment stones, or in acute cholecystitis, cholangitis, biliary obstruction, gallstone pancreatitis or biliary-gastrointestinal fistula\n• Safety beyond 24 months of use not established\n• Monitor dissolution by ultrasound/cholecystography during therapy',
   'Rótulo aprovado DailyMed (Ursodiol Capsule, Strides Pharma; setID 9a6c1928-2d52-4d9a-8e83-f71892a7e98d).',
   'DailyMed approved label (Ursodiol Capsule, Strides Pharma; setID 9a6c1928-2d52-4d9a-8e83-f71892a7e98d).'),
  ('artesunato',
   E'Tratamento da malária grave por Plasmodium falciparum em adultos e crianças, por via intravenosa, geralmente seguido de terapêutica de consolidação oral com um antimalárico de ação prolongada.',
   E'Treatment of severe malaria caused by Plasmodium falciparum in adults and children, administered intravenously, usually followed by oral consolidation therapy with a long-acting antimalarial.',
   E'Pró-fármaco da artemisinina, rapidamente convertido em dihidroartemisinina (DHA), um endoperóxido ativo contra os estádios eritrocitários do parasita. Usado no tratamento da malária grave por via parentérica; não deve ser usado isolado em monoterapia para malária não complicada.',
   E'Artemisinin prodrug rapidly converted to dihydroartemisinin (DHA), an endoperoxide active against the erythrocytic stages of the parasite. Used parenterally in severe malaria; not to be used alone as monotherapy for uncomplicated malaria.',
   E'• Malária grave por Plasmodium falciparum (adultos e crianças), incluindo malária cerebral, anemia grave, insuficiência renal ou respiratória, hiperparasitemia',
   E'• Severe malaria due to Plasmodium falciparum (adults and children), including cerebral malaria, severe anemia, renal or respiratory failure, hyperparasitemia',
   E'• Náuseas, vómitos e anorexia\n• Reticulocitopenia tardia e anemia tardia (hemólise retardada pós-tratamento)\n• Alterações transitórias das transaminases\n• Cardiotoxicidade (prolongamento do QT, raro)\n• Neurotoxicidade (tonturas, convulsões — rara)',
   E'• Nausea, vomiting and anorexia\n• Late reticulocytopenia and late anemia (post-treatment hemolysis)\n• Transient transaminase elevations\n• Cardiotoxicity (QT prolongation, rare)\n• Neurotoxicity (dizziness, seizures — rare)',
   E'• Administrar por via intravenosa (nunca intramuscular) na dose de 2,4 mg/kg às 0, 12 e 24 horas, seguida de terapêutica oral de consolidação\n• Não utilizar em monoterapia para malária não complicada\n• Vigiar sinais de hemólise tardia após o tratamento',
   E'• Administer intravenously (never intramuscularly) at 2.4 mg/kg at 0, 12 and 24 hours, followed by oral consolidation therapy\n• Do not use as monotherapy for uncomplicated malaria\n• Monitor for signs of late hemolysis after treatment',
   'SmPC-padrão WHO-prequalificado (MA152) e EMA (Artesunate Amivas).',
   'WHO-prequalified model SmPC (MA152) and EMA (Artesunate Amivas).'),
  ('benzilpenicilina_benzatina',
   E'Tratamento de infeções por microrganismos sensíveis à penicilina G que requerem níveis séricos prolongados, incluindo sífilis (todas as fases), profilaxia da febre reumática, escarlatina, erisipela e faringite estreptocócica.',
   E'Treatment of infections due to penicillin G-sensitive microorganisms requiring prolonged serum levels, including syphilis (all stages), prophylaxis of rheumatic fever, scarlet fever, erysipelas and streptococcal pharyngitis.',
   E'Sal de benzatina da penicilina G de solubilidade extremamente baixa, o que resulta em libertação lenta a partir do local de injeção intramuscular e níveis séricos baixos mas prolongados (até 4 semanas após 1,2 milhões de unidades). Hidrolisa-se em penicilina G, que inibe a síntese da parede celular bacteriana.',
   E'Benzathine salt of penicillin G with extremely low solubility, resulting in slow release from the intramuscular injection site and low but prolonged serum levels (up to 4 weeks after 1.2 million units). It is hydrolyzed to penicillin G, which inhibits bacterial cell-wall synthesis.',
   E'• Sífilis (todas as fases, incluindo sífilis latente e neurosífilis)\n• Profilaxia da febre reumática\n• Infeções estreptocócicas (faringite, escarlatina, erisipela)\n• Outras infeções por microrganismos sensíveis que beneficiam de níveis séricos prolongados',
   E'• Syphilis (all stages, including latent syphilis and neurosyphilis)\n• Prophylaxis of rheumatic fever\n• Streptococcal infections (pharyngitis, scarlet fever, erysipelas)\n• Other infections due to susceptible organisms benefiting from prolonged serum levels',
   E'• Reações de hipersensibilidade (erupções, urticária, anafilaxia)\n• Reação de Jarisch-Herxheimer no tratamento da sífilis\n• Síndrome de Stevens-Johnson e DRESS (pós-comercialização)\n• Isquemia miocárdica aguda com ou sem enfarte como parte de reação alérgica\n• Dor e inflamação no local de injeção',
   E'• Hypersensitivity reactions (rash, urticaria, anaphylaxis)\n• Jarisch-Herxheimer reaction during syphilis treatment\n• Stevens-Johnson syndrome and DRESS (postmarketing)\n• Acute myocardial ischemia with or without infarction as part of an allergic reaction\n• Pain and inflammation at the injection site',
   E'• NUNCA administrar por via intravenosa (risco de paragem cardiorrespiratória e morte) — exclusivamente intramuscular profunda\n• Indagar sobre história de hipersensibilidade a penicilinas antes de iniciar\n• Vigiar reação de Jarisch-Herxheimer no tratamento da sífilis',
   E'• NEVER administer intravenously (risk of cardiorespiratory arrest and death) — deep intramuscular injection only\n• Inquire about penicillin hypersensitivity before starting\n• Watch for Jarisch-Herxheimer reaction during syphilis treatment',
   'Rótulo aprovado DailyMed (Bicillin L-A, Pfizer; setID 012d46f1-d0a0-4676-a879-cd320297ab16).',
   'DailyMed approved label (Bicillin L-A, Pfizer; setID 012d46f1-d0a0-4676-a879-cd320297ab16).'),
  ('butilbrometo_hioscina',
   E'Alívio das dores e cãibras do trato gastrointestinal (estômago e intestino), vias biliares e trato urinário, associadas a espasmo da musculatura lisa, por exemplo na síndrome do intestino irritável.',
   E'Relief of pain and cramps of the gastrointestinal tract (stomach and intestines), biliary tract and urinary tract associated with smooth-muscle spasm, e.g. in irritable bowel syndrome.',
   E'Composto de amónio quaternário com ação anticolinérgica (antimuscarínica) que bloqueia os recetores muscarínicos da musculatura lisa visceral, aliviando o espasmo. Por ser altamente polar, absorve-se pouco por via oral (~8%) e não atravessa a barreira hematoencefálica, pelo que os efeitos centrais são mínimos.',
   E'Quaternary ammonium compound with anticholinergic (antimuscarinic) action that blocks muscarinic receptors of visceral smooth muscle, relieving spasm. Being highly polar, it is poorly absorbed orally (~8%) and does not cross the blood-brain barrier, so central effects are minimal.',
   E'• Espasmos do trato gastrointestinal (síndrome do intestino irritável)\n• Espasmos das vias biliares e urinárias\n• Dismenorreia (em associação, conforme indicações aprovadas localmente)',
   E'• Spasms of the gastrointestinal tract (irritable bowel syndrome)\n• Spasms of the biliary and urinary tracts\n• Dysmenorrhea (in combination, per locally approved indications)',
   E'• Boca seca (o mais frequente)\n• Taquicardia e palpitações (raro)\n• Retenção urinária e obstipação (raro)\n• Reações de hipersensibilidade (urticária, prurido, dispneia — raras)\n• Midríase e perturbações da acomodação visual (raro)',
   E'• Dry mouth (most common)\n• Tachycardia and palpitations (rare)\n• Urinary retention and constipation (rare)\n• Hypersensitivity reactions (urticaria, pruritus, dyspnea — rare)\n• Mydriasis and accommodation disturbances (rare)',
   E'• Evitar em doentes com glaucoma de ângulo fechado, hipertrofia prostática com retenção urinária, obstrução gastrointestinal ou taquiarritmias\n• Usar com precaução na gravidez e durante a amamentação\n• Não conduzir se ocorrerem perturbações visuais',
   E'• Avoid in angle-closure glaucoma, prostatic hypertrophy with urinary retention, gastrointestinal obstruction or tachyarrhythmias\n• Use with caution in pregnancy and breastfeeding\n• Do not drive if visual disturbances occur',
   'SmPC Buscopan (EMC-UK, product 1775).',
   'Buscopan SmPC (EMC-UK, product 1775).'),
-- ---------------------------------------------------------------------
-- Perfis — B2 (cefalexina, cefazolina, cefepima, cefotaxima, cefuroxima)
-- ---------------------------------------------------------------------
  ('cefalexina',
   E'Antibiótico cefalosporínico de primeira geração indicado no tratamento de infeções respiratórias (Streptococcus pneumoniae e S. pyogenes), otite média, infeções da pele e tecidos moles e infeções urinárias e ósseas por microrganismos sensíveis.',
   E'First-generation cephalosporin indicated for respiratory tract infections (Streptococcus pneumoniae and S. pyogenes), otitis media, skin and skin structure infections, and urinary tract and bone infections due to susceptible organisms.',
   E'Cefalosporina de 1.ª geração bactericida que inibe a síntese da parede celular bacteriana. Ativa contra estreptococos, estafilococos (exceto MRSA) e muitos bacilos Gram-negativos; sem atividade contra Pseudomonas, Enterobacter e a maioria dos anaeróbios.',
   E'First-generation bactericidal cephalosporin that inhibits bacterial cell-wall synthesis. Active against streptococci, staphylococci (except MRSA) and many Gram-negative bacilli; no activity against Pseudomonas, Enterobacter or most anaerobes.',
   E'• Infeções respiratórias (Streptococcus pneumoniae, Streptococcus pyogenes)\n• Otite média (S. pneumoniae, H. influenzae, S. aureus, S. pyogenes, M. catarrhalis)\n• Infeções da pele e tecidos moles\n• Infeções urinárias e ósseas por microrganismos sensíveis',
   E'• Respiratory tract infections (Streptococcus pneumoniae, Streptococcus pyogenes)\n• Otitis media (S. pneumoniae, H. influenzae, S. aureus, S. pyogenes, M. catarrhalis)\n• Skin and skin structure infections\n• Urinary tract and bone infections due to susceptible organisms',
   E'• Diarreia (incluindo colite por Clostridium difficile)\n• Náuseas e vómitos\n• Erupções cutâneas, urticária, angioedema, anafilaxia\n• Eritema multiforme, síndrome de Stevens-Johnson, necrólise epidérmica tóxica (raros)\n• Tonturas, cefaleias e, raramente, convulsões',
   E'• Diarrhea (including Clostridium difficile-associated colitis)\n• Nausea and vomiting\n• Rash, urticaria, angioedema, anaphylaxis\n• Erythema multiforme, Stevens-Johnson syndrome, toxic epidermal necrolysis (rare)\n• Dizziness, headache and, rarely, seizures',
   E'• Indagar sobre hipersensibilidade a cefalosporinas, penicilinas e outros beta-lactâmicos (reação cruzada até ~10% nos alérgicos à penicilina)\n• Vigiar diarreia associada a Clostridium difficile\n• Risco de convulsões em doentes com insuficiência renal (ajustar dose)\n• Monitorizar tempo de protrombina em doentes de risco',
   E'• Inquire about hypersensitivity to cephalosporins, penicillins and other beta-lactams (cross-reactivity up to ~10% in penicillin-allergic patients)\n• Watch for Clostridium difficile-associated diarrhea\n• Seizure risk in renal impairment (adjust dose)\n• Monitor prothrombin time in at-risk patients',
   'Rótulo aprovado DailyMed (Cephalexin Capsule; setID b73593ce-0b1f-4371-bae1-140742de3b42).',
   'DailyMed approved label (Cephalexin Capsule; setID b73593ce-0b1f-4371-bae1-140742de3b42).'),
  ('cefazolina',
   E'Antibiótico cefalosporínico de primeira geração para administração parentérica, indicado no tratamento de infeções respiratórias, urinárias, biliares, osteoarticulares, da pele e tecidos moles, sépsis e endocardite por microrganismos sensíveis, e na profilaxia cirúrgica.',
   E'First-generation parenteral cephalosporin indicated for respiratory, urinary, biliary, bone and joint, skin and soft-tissue infections, septicemia and endocarditis due to susceptible organisms, and for surgical prophylaxis.',
   E'Cefalosporina de 1.ª geração bactericida que inibe a síntese da parede celular bacteriana. Boa atividade contra estafilococos (incluindo produtores de penicilinase) e estreptococos; usada habitualmente em profilaxia cirúrgica pela sua boa penetração tecidular e semivida adequada.',
   E'First-generation bactericidal cephalosporin that inhibits bacterial cell-wall synthesis. Good activity against staphylococci (including penicillinase producers) and streptococci; commonly used for surgical prophylaxis owing to good tissue penetration and adequate half-life.',
   E'• Infeções respiratórias (S. pneumoniae, Klebsiella spp., H. influenzae, S. aureus)\n• Infeções urinárias, biliares e osteoarticulares\n• Sépsis e endocardite\n• Profilaxia cirúrgica de infeção do local cirúrgico',
   E'• Respiratory tract infections (S. pneumoniae, Klebsiella spp., H. influenzae, S. aureus)\n• Urinary, biliary and bone/joint infections\n• Septicemia and endocarditis\n• Surgical site infection prophylaxis',
   E'• Diarreia, náuseas, vómitos, candidíase oral, colite pseudomembranosa\n• Anafilaxia, eosinofilia, prurido, febre medicamentosa, erupções cutâneas, síndrome de Stevens-Johnson\n• Neutropenia, leucopenia, trombocitopenia, trombocitose\n• Elevação transitória das transaminases, fosfatase alcalina e BUN/creatinina\n• Flebite no local de infusão',
   E'• Diarrhea, nausea, vomiting, oral candidiasis, pseudomembranous colitis\n• Anaphylaxis, eosinophilia, itching, drug fever, rash, Stevens-Johnson syndrome\n• Neutropenia, leukopenia, thrombocytopenia, thrombocythemia\n• Transient elevations of transaminases, alkaline phosphatase and BUN/creatinine\n• Phlebitis at the infusion site',
   E'• Indagar sobre hipersensibilidade a cefalosporinas, penicilinas e outros beta-lactâmicos antes de iniciar\n• Ajustar dose na insuficiência renal (excreção renal predominante)\n• Vigiar colite pseudomembranosa durante e após o tratamento',
   E'• Inquire about hypersensitivity to cephalosporins, penicillins and other beta-lactams before starting\n• Adjust dose in renal impairment (predominantly renally excreted)\n• Watch for pseudomembranous colitis during and after therapy',
   'Rótulo aprovado DailyMed (Cefazolin Injection, WG Critical Care; setID 1999084a-124c-45f9-801f-416a1b942c96).',
   'DailyMed approved label (Cefazolin Injection, WG Critical Care; setID 1999084a-124c-45f9-801f-416a1b942c96).'),
  ('cefepima',
   E'Antibiótico cefalosporínico de quarta geração para uso parentérico, indicado em pneumonia (moderada a grave), terapêutica empírica do doente neutropénico febril, infeções intra-abdominais, urinárias complicadas, da pele e tecidos moles e sépsis.',
   E'Fourth-generation parenteral cephalosporin indicated for pneumonia (moderate to severe), empiric therapy of febrile neutropenic patients, intra-abdominal infections, complicated urinary tract infections, skin and soft-tissue infections, and septicemia.',
   E'Cefalosporina de 4.ª geração com espectro alargado, estável à maioria das beta-lactamases cromossómicas, com atividade contra Pseudomonas aeruginosa, Enterobacter spp. e cocos Gram-positivos. Como os restantes beta-lactâmicos, o tempo acima da CMI correlaciona-se com a eficácia.',
   E'Fourth-generation cephalosporin with extended spectrum, stable against most chromosomal beta-lactamases, active against Pseudomonas aeruginosa, Enterobacter spp. and Gram-positive cocci. As with other beta-lactams, time above the MIC correlates with efficacy.',
   E'• Pneumonia moderada a grave (S. pneumoniae, P. aeruginosa, K. pneumoniae, Enterobacter spp.)\n• Terapêutica empírica da neutropenia febril\n• Infeções intra-abdominais e urinárias complicadas\n• Infeções da pele e tecidos moles e sépsis',
   E'• Moderate to severe pneumonia (S. pneumoniae, P. aeruginosa, K. pneumoniae, Enterobacter spp.)\n• Empiric therapy of febrile neutropenia\n• Complicated intra-abdominal and urinary tract infections\n• Skin and soft-tissue infections and septicemia',
   E'• Reações de hipersensibilidade (erupções, prurido, anafilaxia)\n• Neurotoxicidade: encefalopatia, mioclonias e convulsões (especialmente na insuficiência renal sem ajuste de dose)\n• Diarreia associada a Clostridioides difficile\n• Náuseas, vómitos, diarreia, cefaleias, febre\n• Eosinofilia, anemia, neutropenia, trombocitopenia (reversíveis)',
   E'• Hypersensitivity reactions (rash, pruritus, anaphylaxis)\n• Neurotoxicity: encephalopathy, myoclonus and seizures (especially in renal impairment without dose adjustment)\n• Clostridioides difficile-associated diarrhea\n• Nausea, vomiting, diarrhea, headache, fever\n• Eosinophilia, anemia, neutropenia, thrombocytopenia (reversible)',
   E'• Ajustar dose na insuficiência renal (risco de neurotoxicidade com doses não ajustadas)\n• Indagar sobre alergia a beta-lactâmicos (reação cruzada até ~10% nos alérgicos à penicilina)\n• Vigiar diarreia associada a Clostridioides difficile',
   E'• Adjust dose in renal impairment (neurotoxicity risk with unadjusted doses)\n• Inquire about beta-lactam allergy (cross-reactivity up to ~10% in penicillin-allergic patients)\n• Watch for Clostridioides difficile-associated diarrhea',
   'Rótulo aprovado DailyMed (Cefepime Injection, WG Critical Care; setID 5fd857e5-591f-44ca-80cf-fd903660b03c).',
   'DailyMed approved label (Cefepime Injection, WG Critical Care; setID 5fd857e5-591f-44ca-80cf-fd903660b03c).'),
  ('cefotaxima',
   E'Antibiótico cefalosporínico de terceira geração para uso parentérico, indicado no tratamento de infeções graves por microrganismos sensíveis: respiratórias, urinárias, ginecológicas, sépsis, endocardite, meningite e infeções intra-abdominais.',
   E'Third-generation parenteral cephalosporin indicated for serious infections due to susceptible organisms: respiratory, urinary, gynecologic, septicemia, endocarditis, meningitis and intra-abdominal infections.',
   E'Cefalosporina de 3.ª geração estável à maioria das beta-lactamases, com atividade alargada contra Gram-negativos (incluindo H. influenzae, Neisseria e muitos Enterobacterales) e boa penetração no LCR com meninges inflamadas; o metabolito desacetil contribui para a atividade bactericida.',
   E'Third-generation cephalosporin stable to most beta-lactamases, with extended Gram-negative activity (including H. influenzae, Neisseria and many Enterobacterales) and good CSF penetration with inflamed meninges; the desacetyl metabolite contributes to bactericidal activity.',
   E'• Infeções respiratórias baixas (pneumonia por S. pneumoniae, S. pyogenes, S. aureus, E. coli, Klebsiella, H. influenzae)\n• Infeções urinárias e ginecológicas\n• Sépsis, endocardite e meningite\n• Infeções intra-abdominais e da pele/tecidos moles',
   E'• Lower respiratory tract infections (pneumonia due to S. pneumoniae, S. pyogenes, S. aureus, E. coli, Klebsiella, H. influenzae)\n• Urinary and gynecologic infections\n• Septicemia, endocarditis and meningitis\n• Intra-abdominal and skin/soft-tissue infections',
   E'• Reações locais (inflamação no local de injeção IV ~4,3%; dor, endurecimento após IM)\n• Hipersensibilidade (erupções, prurido, febre, eosinofilia ~2,4%)\n• Gastrointestinais: colite, diarreia, náuseas, vómitos (~1,4%)\n• Neutropenia, trombocitopenia e anemia hemolítica (pouco frequentes)\n• Elevação transitória das transaminases',
   E'• Local reactions (injection-site inflammation with IV ~4.3%; pain, induration after IM)\n• Hypersensitivity (rash, pruritus, fever, eosinophilia ~2.4%)\n• Gastrointestinal: colitis, diarrhea, nausea, vomiting (~1.4%)\n• Neutropenia, thrombocytopenia and hemolytic anemia (infrequent)\n• Transient transaminase elevations',
   E'• Indagar sobre hipersensibilidade a cefalosporinas e penicilinas antes de iniciar\n• Ajustar dose na insuficiência renal\n• Vigiar colite pseudomembranosa e discrasias sanguíneas em tratamentos prolongados',
   E'• Inquire about hypersensitivity to cephalosporins and penicillins before starting\n• Adjust dose in renal impairment\n• Watch for pseudomembranous colitis and blood dyscrasias in prolonged therapy',
   'Rótulo aprovado DailyMed (Cefotaxime Injection; setID 8efe3bd0-c43a-2bd6-e053-2a95a90a92fa).',
   'DailyMed approved label (Cefotaxime Injection; setID 8efe3bd0-c43a-2bd6-e053-2a95a90a92fa).'),
  ('cefuroxima',
   E'Antibiótico cefalosporínico de segunda geração (profármaco axetil oral), indicado em faringite/amigdalite, otite média aguda, sinusite, exacerbações agudas de bronquite crónica, infeções urinárias não complicadas e infeções da pele e tecidos moles.',
   E'Second-generation cephalosporin (oral axetil prodrug) indicated for pharyngitis/tonsillitis, acute otitis media, sinusitis, acute exacerbations of chronic bronchitis, uncomplicated urinary tract infections and skin/soft-tissue infections.',
   E'Cefalosporina de 2.ª geração que inibe a síntese da parede celular. O axetil é absorvido no trato gastrointestinal e hidrolisado por esterases a cefuroxima ativa. Espectro alargado a Gram-negativos, incluindo beta-lactamases de H. influenzae e M. catarrhalis.',
   E'Second-generation cephalosporin that inhibits cell-wall synthesis. Axetil is absorbed from the GI tract and hydrolyzed by esterases to active cefuroxime. Extended Gram-negative spectrum, including beta-lactamases of H. influenzae and M. catarrhalis.',
   E'• Faringite/amigdalite por Streptococcus pyogenes\n• Otite média aguda e sinusite bacteriana aguda\n• Exacerbações agudas de bronquite crónica\n• Infeções urinárias não complicadas e da pele/tecidos moles',
   E'• Pharyngitis/tonsillitis due to Streptococcus pyogenes\n• Acute otitis media and acute bacterial sinusitis\n• Acute exacerbations of chronic bronchitis\n• Uncomplicated urinary tract and skin/soft-tissue infections',
   E'• Diarreia, náuseas, vómitos e dor abdominal\n• Reações de hipersensibilidade (erupções, urticária, anafilaxia)\n• Candidíase oral e vaginal\n• Cefaleias e tonturas\n• Elevação transitória das transaminases',
   E'• Diarrhea, nausea, vomiting and abdominal pain\n• Hypersensitivity reactions (rash, urticaria, anaphylaxis)\n• Oral and vaginal candidiasis\n• Headache and dizziness\n• Transient transaminase elevations',
   E'• Administrar com alimentos (aumenta a absorção)\n• Indagar sobre hipersensibilidade a beta-lactâmicos (risco de reações graves em alérgicos à penicilina)\n• Ajustar dose na insuficiência renal\n• Não usar na prevenção da febre reumática (eficácia não estabelecida)',
   E'• Administer with food (enhances absorption)\n• Inquire about beta-lactam hypersensitivity (risk of severe reactions in penicillin-allergic patients)\n• Adjust dose in renal impairment\n• Not for prevention of rheumatic fever (efficacy not established)',
   'Rótulo aprovado DailyMed (Cefuroxime Axetil Tablet; setID 76cec54f-d167-4298-951b-5411a3c47f4a).',
   'DailyMed approved label (Cefuroxime Axetil Tablet; setID 76cec54f-d167-4298-951b-5411a3c47f4a).'),
-- ---------------------------------------------------------------------
-- Perfis — B3 (etilefrina, famotidina, fenoximetilpenicilina, filgrastim, fondaparinux)
-- ---------------------------------------------------------------------
  ('etilefrina',
   E'Hipotensão ortostática e estados hipotensivos, incluindo hipotensão associada a anestesia, choque hipovolémico (em associação com expansores de volume) e síncope vasovagal, conforme indicações aprovadas localmente.',
   E'Orthostatic hypotension and hypotensive states, including anesthesia-associated hypotension, hypovolemic shock (with volume expanders) and vasovagal syncope, per locally approved indications.',
   E'Simpaticomimético de ação direta sobre recetores alfa e beta-adrenérgicos, com efeito predominantemente pressor (aumento da resistência vascular periférica e da contratilidade miocárdica). Sofre efeito de primeira passagem extenso; o principal metabolito é o sulfato fenólico conjugado.',
   E'Direct-acting sympathomimetic on alpha and beta-adrenergic receptors, with predominantly pressor effect (increased peripheral vascular resistance and myocardial contractility). Undergoes extensive first-pass metabolism; the main metabolite is the phenolic sulfate conjugate.',
   E'• Hipotensão ortostática sintomática\n• Estados hipotensivos (incluindo associados a anestesia)\n• Choque hipovolémico (em associação com expansores de volume)',
   E'• Symptomatic orthostatic hypotension\n• Hypotensive states (including anesthesia-associated)\n• Hypovolemic shock (with volume expanders)',
   E'• Palpitações e taquicardia\n• Ansiedade, tremor e cefaleias\n• Hipertensão arterial (com doses elevadas)\n• Arritmias cardíacas (em doentes predispostos)',
   E'• Palpitations and tachycardia\n• Anxiety, tremor and headache\n• Hypertension (at high doses)\n• Cardiac arrhythmias (in predisposed patients)',
   E'• Evitar em hipertiroidismo, feocromocitoma, cardiopatia isquémica grave, arritmias e hipertensão não controlada\n• Vigiar pressão arterial e frequência cardíaca durante a perfusão\n• Usar com precaução na gravidez',
   E'• Avoid in hyperthyroidism, pheochromocytoma, severe ischemic heart disease, arrhythmias and uncontrolled hypertension\n• Monitor blood pressure and heart rate during infusion\n• Use with caution in pregnancy',
   'Hengstmann JH 1975 (PMID 9300) — disposition fisiológica da etilefrina no homem.',
   'Hengstmann JH 1975 (PMID 9300) — physiological disposition of etilefrine in man.'),
  ('famotidina',
   E'Anti-H2 indicado no tratamento da úlcera duodenal ativa, úlcera gástrica ativa, doença de refluxo gastroesofágico não erosiva sintomática e esofagite erosiva por DRGE, e na redução do risco de recorrência da úlcera duodenal.',
   E'H2-receptor antagonist indicated for active duodenal ulcer, active gastric ulcer, symptomatic nonerosive GERD and erosive esophagitis due to GERD, and reduction of duodenal ulcer recurrence risk.',
   E'Antagonista competitivo dos recetores H2 da histamina nas células parietais gástricas, inibindo a secreção ácida basal e noturna e a estimulada por alimento e pentagastrina. O efeito antisecretor inicia-se em ~1 hora e dura 10–12 horas com doses de 20–40 mg.',
   E'Competitive antagonist of histamine H2 receptors on gastric parietal cells, inhibiting basal, nocturnal and food-/pentagastrin-stimulated acid secretion. Antisecretory effect starts within ~1 hour and lasts 10–12 hours with 20–40 mg doses.',
   E'• Úlcera duodenal ativa\n• Úlcera gástrica ativa\n• DRGE não erosiva sintomática e esofagite erosiva\n• Condições de hipersecreção patológica (síndrome de Zollinger-Ellison, neoplasias endócrinas múltiplas)\n• Redução do risco de recorrência de úlcera duodenal',
   E'• Active duodenal ulcer\n• Active gastric ulcer\n• Symptomatic nonerosive GERD and erosive esophagitis\n• Pathological hypersecretory conditions (Zollinger-Ellison syndrome, multiple endocrine neoplasias)\n• Reduction of duodenal ulcer recurrence risk',
   E'• Cefaleias, tonturas e obstipação\n• Diarreia\n• Reações adversas no SNC em idosos e doentes com insuficiência renal: confusão, delírio, alucinações, agitação, convulsões, letargia\n• Reações de hipersensibilidade graves (anafilaxia — rara)',
   E'• Headache, dizziness and constipation\n• Diarrhea\n• CNS adverse reactions in the elderly and in renal impairment: confusion, delirium, hallucinations, agitation, seizures, lethargy\n• Serious hypersensitivity reactions (anaphylaxis — rare)',
   E'• Reduzir dose na insuficiência renal (níveis sanguíneos aumentados; risco de reações no SNC)\n• Excluir neoplasia gástrica antes de iniciar em doentes com sintomas de alarme\n• Vigiar sintomas neurológicos em idosos e insuficientes renais',
   E'• Reduce dose in renal impairment (increased blood levels; CNS reaction risk)\n• Exclude gastric malignancy before starting in patients with alarm symptoms\n• Watch for neurological symptoms in the elderly and renally impaired',
   'Rótulo aprovado DailyMed (Ibuprofen and Famotidine Tablet, Doctor Reddy; setID 9f5de6af-e555-4efd-a3ed-b72c34c051b6).',
   'DailyMed approved label (Ibuprofen and Famotidine Tablet, Doctor Reddy; setID 9f5de6af-e555-4efd-a3ed-b72c34c051b6).'),
  ('fenoximetilpenicilina',
   E'Antibiótico penicilínico oral indicado no tratamento de infeções ligeiras a moderadamente graves por microrganismos sensíveis, incluindo faringite estreptocócica, profilaxia da febre reumática e infeções odontogénicas.',
   E'Oral penicillin indicated for mild to moderately severe infections due to susceptible organisms, including streptococcal pharyngitis, rheumatic fever prophylaxis and odontogenic infections.',
   E'Penicilina oral (sal potássico da penicilina V) bactericida contra microrganismos sensíveis na fase de multiplicação ativa, por inibição da síntese da parede celular. Mais resistente ao ácido gástrico que a penicilina G, podendo ser administrada com as refeições.',
   E'Oral penicillin (potassium salt of penicillin V) bactericidal against susceptible organisms during active multiplication by inhibiting cell-wall synthesis. More resistant to gastric acid than penicillin G and may be given with meals.',
   E'• Faringite e amigdalite estreptocócica\n• Profilaxia da febre reumática\n• Infeções odontogénicas e da pele/tecidos moles\n• Escarlatina e erisipela',
   E'• Streptococcal pharyngitis and tonsillitis\n• Rheumatic fever prophylaxis\n• Odontogenic and skin/soft-tissue infections\n• Scarlet fever and erysipelas',
   E'• Náuseas, vómitos, desconforto epigástrico, diarreia e língua negra pilosa (os mais comuns)\n• Erupções cutâneas (maculopapulares a dermatite esfoliativa), urticária, reações tipo doença do soro, edema laríngeo e anafilaxia\n• Febre e eosinofilia\n• Anemia hemolítica, leucopenia, trombocitopenia (pouco frequentes)',
   E'• Nausea, vomiting, epigastric distress, diarrhea and black hairy tongue (most common)\n• Skin eruptions (maculopapular to exfoliative dermatitis), urticaria, serum-sickness-like reactions, laryngeal edema and anaphylaxis\n• Fever and eosinophilia\n• Hemolytic anemia, leukopenia, thrombocytopenia (infrequent)',
   E'• Contraindicado em doentes com hipersensibilidade prévia a qualquer penicilina\n• Vigiar reações de hipersensibilidade, incluindo anafilaxia fatal\n• Ajustar dose na insuficiência renal grave',
   E'• Contraindicated in patients with previous hypersensitivity to any penicillin\n• Watch for hypersensitivity reactions, including fatal anaphylaxis\n• Adjust dose in severe renal impairment',
   'Rótulo aprovado DailyMed (Penicillin V Potassium Tablet; setID 64ac283c-fe6a-49f0-ae85-90ab98e38272).',
   'DailyMed approved label (Penicillin V Potassium Tablet; setID 64ac283c-fe6a-49f0-ae85-90ab98e38272).'),
  ('filgrastim',
   E'Fator estimulante de colónias de granulócitos (G-CSF) indicado para diminuir a incidência de infeção, manifestada por neutropenia febril, em doentes com neoplasias não mieloides a receber quimioterapia mielossupressora, e para reduzir o tempo de recuperação de neutrófilos após indução/consolidação de leucemia mieloide aguda.',
   E'Granulocyte colony-stimulating factor (G-CSF) indicated to decrease the incidence of infection, manifested by febrile neutropenia, in patients with nonmyeloid malignancies receiving myelosuppressive chemotherapy, and to reduce the time to neutrophil recovery following induction/consolidation chemotherapy of acute myeloid leukemia.',
   E'Glicoproteína que se liga a recetores específicos nas células progenitoras hematopoiéticas, estimulando a proliferação, diferenciação e ativação funcional dos neutrófilos. É específico da linhagem neutrofílica, com efeitos mínimos noutras células hematopoiéticas.',
   E'Glycoprotein that binds to specific receptors on hematopoietic progenitor cells, stimulating neutrophil proliferation, differentiation and functional activation. It is lineage-specific for neutrophils, with minimal effects on other hematopoietic cells.',
   E'• Redução da incidência de infeção (neutropenia febril) em doentes com neoplasias não mieloides sob quimioterapia mielossupressora\n• Redução do tempo de recuperação de neutrófilos e da duração da febre após indução/consolidação de LMA\n• (Outras indicações aprovadas: mobilização de células progenitoras, neutropenia grave crónica)',
   E'• Decrease incidence of infection (febrile neutropenia) in patients with nonmyeloid malignancies receiving myelosuppressive chemotherapy\n• Reduce time to neutrophil recovery and duration of fever following AML induction/consolidation\n• (Other approved indications: progenitor cell mobilization, severe chronic neutropenia)',
   E'• Dor óssea (frequente)\n• Pirexia, fadiga, dor torácica e dor generalizada\n• Náuseas, diarreia, obstipação\n• Trombocitopenia\n• Esplenomegália e rutura esplénica (rara, potencialmente fatal)\n• SDRA (rara)\n• Reações alérgicas graves incluindo anafilaxia',
   E'• Bone pain (common)\n• Pyrexia, fatigue, chest pain and generalized pain\n• Nausea, diarrhea, constipation\n• Thrombocytopenia\n• Splenomegaly and splenic rupture (rare, potentially fatal)\n• ARDS (rare)\n• Serious allergic reactions including anaphylaxis',
   E'• Avaliar dor no quadrante superior esquerdo ou no ombro por rutura esplénica\n• Vigiar febre e infiltrados pulmonares/desconforto respiratório por SDRA\n• Contraindicado em doentes com reações alérgicas graves a G-CSF\n• Monitorizar hemograma durante o tratamento',
   E'• Evaluate left upper quadrant or shoulder pain for splenic rupture\n• Monitor fever and lung infiltrates/respiratory distress for ARDS\n• Contraindicated in patients with serious allergic reactions to G-CSF\n• Monitor blood counts during therapy',
   'Rótulo aprovado DailyMed (NEUPOGEN, Amgen; setID 97cc73cc-b5b7-458a-a933-77b00523e193).',
   'DailyMed approved label (NEUPOGEN, Amgen; setID 97cc73cc-b5b7-458a-a933-77b00523e193).'),
  ('fondaparinux',
   E'Anticoagulante injetável indicado na profilaxia de trombose venosa profunda em doentes submetidos a cirurgia ortopédica major (fratura da anca, artroplastia da anca e do joelho) e abdominal de risco, e no tratamento da TVP aguda e da embolia pulmonar aguda.',
   E'Injectable anticoagulant indicated for prophylaxis of deep vein thrombosis in patients undergoing major orthopedic surgery (hip fracture, hip and knee replacement) and at-risk abdominal surgery, and for treatment of acute DVT and acute pulmonary embolism.',
   E'Pentassacarídeo sintético que se liga seletivamente à antitrombina III, potenciando (~300x) a neutralização do fator Xa, interrompendo a cascata da coagulação e inibindo a formação de trombina. Não inativa a trombina nem afeta a função plaquetária.',
   E'Synthetic pentasaccharide that selectively binds antithrombin III, potentiating (~300-fold) the neutralization of factor Xa, interrupting the coagulation cascade and inhibiting thrombin formation. It does not inactivate thrombin nor affect platelet function.',
   E'• Profilaxia de TVP em cirurgia de fratura da anca (incluindo profilaxia prolongada)\n• Profilaxia de TVP em artroplastia da anca e do joelho\n• Profilaxia de TVP em cirurgia abdominal de risco tromboembólico\n• Tratamento da TVP aguda e da embolia pulmonar aguda (em associação com varfarina)',
   E'• DVT prophylaxis in hip fracture surgery (including extended prophylaxis)\n• DVT prophylaxis in hip and knee replacement surgery\n• DVT prophylaxis in at-risk abdominal surgery\n• Treatment of acute DVT and acute pulmonary embolism (with warfarin)',
   E'• Hemorragia major (incluindo intracraniana, retroperitoneal)\n• Anemia e hematomas no local de injeção\n• Trombocitopenia\n• Hematoma espinal/epidural com anestesia neuraxial (risco de paralisia)\n• Elevação das transaminases',
   E'• Major bleeding (including intracranial, retroperitoneal)\n• Anemia and injection-site hematomas\n• Thrombocytopenia\n• Spinal/epidural hematoma with neuraxial anesthesia (paralysis risk)\n• Transaminase elevations',
   E'• Contraindicado na insuficiência renal grave (CrCl < 30 mL/min), hemorragia ativa major, endocardite bacteriana e trombocitopenia associada a anticorpos antiplaquetários\n• Risco hemorrágico aumentado com peso < 50 kg e na insuficiência renal\n• Vigiar sinais de hematoma neuraxial com anestesia espinal/epidural\n• Não usar isolado no tratamento do tromboembolismo venoso',
   E'• Contraindicated in severe renal impairment (CrCl < 30 mL/min), active major bleeding, bacterial endocarditis and antibody-associated thrombocytopenia\n• Increased bleeding risk with body weight < 50 kg and in renal impairment\n• Watch for neuraxial hematoma signs with spinal/epidural anesthesia\n• Not to be used alone for venous thromboembolism treatment',
   'Rótulo aprovado DailyMed (Fondaparinux Sodium Injection, Zydus; setID dffbf7c9-495e-4a33-ac76-57b52f014fc2).',
   'DailyMed approved label (Fondaparinux Sodium Injection, Zydus; setID dffbf7c9-495e-4a33-ac76-57b52f014fc2).'),
-- ---------------------------------------------------------------------
-- Perfis — B4 (ipratropio, memantina, midodrina, montelukast, nistatina)
-- ---------------------------------------------------------------------
  ('ipratropio',
   E'Broncodilatador anticolinérgico de manutenção do broncospasmo associado à doença pulmonar obstrutiva crónica (bronquite crónica e enfisema), isolado ou em associação com outros broncodilatadores, especialmente beta-adrenérgicos.',
   E'Anticholinergic bronchodilator for maintenance treatment of bronchospasm associated with chronic obstructive pulmonary disease (chronic bronchitis and emphysema), alone or with other bronchodilators, especially beta-adrenergics.',
   E'Agente anticolinérgico (parassimpatolítico) que antagoniza a acetilcolina nos recetores muscarínicos do músculo liso brônquico, impedindo o aumento do GMP cíclico intracelular e produzindo broncodilatação. O efeito é predominantemente local, no local de inalação.',
   E'Anticholinergic (parasympatholytic) agent that antagonizes acetylcholine at muscarinic receptors of bronchial smooth muscle, preventing the rise of intracellular cyclic GMP and producing bronchodilation. The effect is predominantly local, at the site of inhalation.',
   E'• Manutenção do broncospasmo na DPOC (bronquite crónica e enfisema)\n• Em associação com beta-agonistas no tratamento da DPOC',
   E'• Maintenance treatment of bronchospasm in COPD (chronic bronchitis and emphysema)\n• In combination with beta-agonists in COPD',
   E'• Bronquite e exacerbações da DPOC\n• Tosse, boca seca, disfonia\n• Náuseas, tonturas e cefaleias\n• Taquicardia, palpitações, dor ocular, retenção urinária e urticária (< 3%)\n• Precipitação ou agravamento de glaucoma de ângulo fechado, midríase e dor ocular aguda',
   E'• Bronchitis and COPD exacerbations\n• Cough, dry mouth, dysphonia\n• Nausea, dizziness and headache\n• Tachycardia, palpitations, eye pain, urinary retention and urticaria (< 3%)\n• Precipitation or worsening of narrow-angle glaucoma, mydriasis and acute eye pain',
   E'• Evitar contacto com os olhos (risco de agravamento de glaucoma de ângulo fechado em doentes predispostos)\n• Não usar como agente único no broncospasmo agudo da exacerbação da DPOC (não estudado)\n• Precaução na hiperplasia prostática e obstrução do colo vesical (retenção urinária)',
   E'• Avoid contact with the eyes (risk of worsening narrow-angle glaucoma in predisposed patients)\n• Not to be used as single agent for acute bronchospasm in COPD exacerbation (not studied)\n• Caution in prostatic hyperplasia and bladder-neck obstruction (urinary retention)',
   'Rótulo aprovado DailyMed (Ipratropium Bromide Solution; setID 6b730dd7-4d93-403a-bfd2-fa0efa298b75).',
   'DailyMed approved label (Ipratropium Bromide Solution; setID 6b730dd7-4d93-403a-bfd2-fa0efa298b75).'),
  ('memantina',
   E'Tratamento da demência moderada a grave do tipo Alzheimer.',
   E'Treatment of moderate to severe dementia of the Alzheimer type.',
   E'Antagonista não competitivo de afinidade baixa a moderada dos recetores NMDA (canal aberto), que se liga preferencialmente aos canais catiónicos operados por NMDA, modulando a excitotoxicidade pelo glutamato sem interferir com a transmissão fisiológica. Não há evidência de que previna ou abrande a neurodegenerescência.',
   E'Low to moderate affinity, uncompetitive (open-channel) NMDA receptor antagonist that binds preferentially to NMDA receptor-operated cation channels, modulating glutamate excitotoxicity without interfering with physiological transmission. There is no evidence it prevents or slows neurodegeneration.',
   E'• Demência moderada a grave do tipo Alzheimer',
   E'• Moderate to severe dementia of the Alzheimer type',
   E'• Tonturas, cefaleias e sonolência\n• Obstipação e vómitos\n• Hipertensão\n• Confusão, alucinações\n• Dispneia e tosse\n• Dor lombar e fadiga',
   E'• Dizziness, headache and somnolence\n• Constipation and vomiting\n• Hypertension\n• Confusion, hallucinations\n• Dyspnea and cough\n• Back pain and fatigue',
   E'• Condições que elevam o pH urinário (alcalinizantes, dieta muito rica em vegetais) diminuem a eliminação renal e aumentam os níveis plasmáticos\n• Precaução na insuficiência renal (ajustar dose) e em doentes com fatores que alteram o pH urinário',
   E'• Conditions that raise urine pH (alkalinizing agents, very vegetarian diet) decrease renal elimination and increase plasma levels\n• Caution in renal impairment (dose adjustment) and in patients with factors altering urine pH',
   'Rótulo aprovado DailyMed (Memantine Hydrochloride Tablet; setID cbfd9d95-f50b-45ff-9857-9f1712c45e56).',
   'DailyMed approved label (Memantine Hydrochloride Tablet; setID cbfd9d95-f50b-45ff-9857-9f1712c45e56).'),
  ('midodrina',
   E'Tratamento da hipotensão ortostática sintomática, em doentes cuja vida é consideravelmente afetada apesar dos cuidados clínicos padrão (incluindo tratamento não farmacológico). Pode causar elevação acentuada da pressão arterial em decúbito.',
   E'Treatment of symptomatic orthostatic hypotension in patients whose lives are considerably impaired despite standard clinical care (including non-pharmacologic treatment). It can cause marked elevation of supine blood pressure.',
   E'Pró-fármaco convertido no metabolito ativo desglimidodrina, agonista alfa-1-adrenérgico que aumenta o tónus arteriolar e venoso, elevando a pressão arterial. Não estimula os recetores beta cardíacos e difunde pouco através da barreira hematoencefálica.',
   E'Prodrug converted to the active metabolite desglymidodrine, an alpha-1-adrenergic agonist that increases arteriolar and venous tone, raising blood pressure. It does not stimulate cardiac beta receptors and diffuses poorly across the blood-brain barrier.',
   E'• Hipotensão ortostática sintomática com compromisso significativo apesar do tratamento padrão',
   E'• Symptomatic orthostatic hypotension with significant impairment despite standard care',
   E'• Hipertensão em decúbito e sentado (as mais frequentes)\n• Parestesias e prurido, principalmente do couro cabeludo\n• Arrepios, calafrios, piloereção\n• Urgência urinária, retenção e frequência urinárias\n• Disúria e erupções cutâneas',
   E'• Supine and sitting hypertension (most frequent)\n• Paresthesia and pruritus, mainly of the scalp\n• Goosebumps, chills, piloerection\n• Urinary urgency, retention and frequency\n• Dysuria and rash',
   E'• Contraindicado em cardiopatia orgânica grave, doença renal aguda, retenção urinária, feocromocitoma, tirotoxicose e hipertensão em decúbito persistente/excessiva\n• Monitorizar pressão arterial em decúbito e ortostatismo\n• Não administrar à noite ou antes de períodos de repouso em decúbito',
   E'• Contraindicated in severe organic heart disease, acute renal disease, urinary retention, pheochromocytoma, thyrotoxicosis and persistent/excessive supine hypertension\n• Monitor supine and standing blood pressure\n• Do not administer at night or before periods of supine rest',
   'Rótulo aprovado DailyMed (Midodrine Hydrochloride Tablet, Northstar Rx; setID 79b712a3-be12-4ea6-ac42-742826685ae5).',
   'DailyMed approved label (Midodrine Hydrochloride Tablet, Northstar Rx; setID 79b712a3-be12-4ea6-ac42-742826685ae5).'),
  ('montelukast',
   E'Antagonista dos recetores dos leucotrienos cisteinílicos, indicado na profilaxia e tratamento crónico da asma, prevenção aguda do broncospasmo induzido pelo exercício e alívio dos sintomas da rinite alérgica sazonal e perene (quando os tratamentos alternativos são insuficientes ou não tolerados).',
   E'Cysteinyl leukotriene receptor antagonist indicated for prophylaxis and chronic treatment of asthma, acute prevention of exercise-induced bronchoconstriction, and relief of seasonal and perennial allergic rhinitis symptoms (when alternatives are inadequate or not tolerated).',
   E'Antagonista oral seletivo e de alta afinidade do recetor CysLT1 dos leucotrienos cisteinílicos (LTC4, LTD4, LTE4), mediadores inflamatórios libertados por mastócitos e eosinófilos, reduzindo o edema das vias aéreas, a contração do músculo liso e a atividade inflamatória na asma e na rinite alérgica.',
   E'Oral, highly selective antagonist of the CysLT1 receptor of cysteinyl leukotrienes (LTC4, LTD4, LTE4), inflammatory mediators released by mast cells and eosinophils, reducing airway edema, smooth-muscle contraction and inflammatory activity in asthma and allergic rhinitis.',
   E'• Profilaxia e tratamento crónico da asma (≥ 15 anos)\n• Prevenção aguda do broncospasmo induzido pelo exercício (≥ 15 anos)\n• Alívio dos sintomas da rinite alérgica sazonal e perene (≥ 15 anos), quando as alternativas são inadequadas',
   E'• Prophylaxis and chronic treatment of asthma (≥ 15 years)\n• Acute prevention of exercise-induced bronchoconstriction (≥ 15 years)\n• Relief of seasonal and perennial allergic rhinitis symptoms (≥ 15 years), when alternatives are inadequate',
   E'• Cefaleias, tonturas, sonolência\n• Dor abdominal, dispepsia, náuseas, diarreia\n• Febre, faringite, tosse, congestão nasal\n• Eventos neuropsiquiátricos (pós-comercialização): agitação, agressividade, ansiedade, depressão, insónia, perturbação da atenção, pensamentos e comportamentos suicidas, tremor',
   E'• Headache, dizziness, somnolence\n• Abdominal pain, dyspepsia, nausea, diarrhea\n• Fever, pharyngitis, cough, nasal congestion\n• Neuropsychiatric events (postmarketing): agitation, aggression, anxiety, depression, insomnia, attention disturbance, suicidal thoughts and behavior, tremor',
   E'• Vigiar eventos neuropsiquiátricos (suspender se ocorrerem)\n• Não indicado para o broncospasmo agudo (usar beta-agonista de ação rápida)\n• Não substituir os corticosteroides inalados no controlo da asma',
   E'• Monitor neuropsychiatric events (discontinue if they occur)\n• Not indicated for acute bronchospasm (use rapid-acting beta-agonist)\n• Not a substitute for inhaled corticosteroids in asthma control',
   'Rótulo aprovado DailyMed (Montelukast Tablet; setID 583a9499-97f0-2ebf-e063-6394a90a35af).',
   'DailyMed approved label (Montelukast Tablet; setID 583a9499-97f0-2ebf-e063-6394a90a35af).'),
  ('nistatina',
   E'Antifúngico poliénico de uso tópico/oral indicado no tratamento da candidíase das mucosas gastrointestinais não esofágica (apresentações orais) e da candidíase cutânea e mucocutânea (apresentações tópicas).',
   E'Polyene antifungal for topical/oral use indicated for non-esophageal gastrointestinal mucosal candidiasis (oral forms) and cutaneous and mucocutaneous candidiasis (topical forms).',
   E'Antifúngico que se liga aos esteróis da membrana celular das espécies de Candida suscetíveis, alterando a permeabilidade e permitindo a fuga de componentes intracelulares, com efeito fungistático e fungicida. Sem atividade apreciável contra bactérias, protozoários ou vírus; não é absorvido pelo trato gastrointestinal.',
   E'Antifungal that binds to sterols in the cell membrane of susceptible Candida species, altering permeability and allowing leakage of intracellular components, with fungistatic and fungicidal effect. No appreciable activity against bacteria, protozoa or viruses; not absorbed from the GI tract.',
   E'• Candidíase das mucosas gastrointestinais não esofágica (via oral)\n• Candidíase cutânea e mucocutânea (formas tópicas)',
   E'• Non-esophageal gastrointestinal mucosal candidiasis (oral)\n• Cutaneous and mucocutaneous candidiasis (topical forms)',
   E'• Irritação oral e sensibilização\n• Diarreia (incluindo um caso de diarreia sanguinolenta), náuseas, vómitos, desconforto gastrointestinal\n• Erupções cutâneas e urticária (raras); síndrome de Stevens-Johnson (muito rara)\n• Taquicardia, broncospasmo, edema facial e mialgia inespecífica (raros)',
   E'• Oral irritation and sensitization\n• Diarrhea (including one case of bloody diarrhea), nausea, vomiting, GI upset\n• Rash and urticaria (rare); Stevens-Johnson syndrome (very rare)\n• Tachycardia, bronchospasm, facial swelling and nonspecific myalgia (rare)',
   E'• Não usar no tratamento de micoses sistémicas\n• Suspender se ocorrer sensibilização ou irritação\n• Em doentes com insuficiência renal em terapia oral, podem ocorrer concentrações plasmáticas significativas',
   E'• Not for treatment of systemic mycoses\n• Discontinue if sensitization or irritation occurs\n• In renally impaired patients on oral therapy, significant plasma concentrations may occur',
   'Rótulo aprovado DailyMed (Nystatin Tablet; setID 197e3046-3e58-4246-b260-f3995dce41a1).',
   'DailyMed approved label (Nystatin Tablet; setID 197e3046-3e58-4246-b260-f3995dce41a1).'),
-- ---------------------------------------------------------------------
-- Perfis — B5 (ondansetron, piperacilina-tazobactam, pirazinamida, poractant alfa, primaquina)
-- ---------------------------------------------------------------------
  ('ondansetron',
   E'Antiemético antagonista dos recetores 5-HT3, indicado na prevenção de náuseas e vómitos associados a quimioterapia cancerígena altamente e moderadamente emetogénica, radioterapia e no pós-operatório.',
   E'5-HT3 receptor antagonist antiemetic indicated for prevention of nausea and vomiting associated with highly and moderately emetogenic cancer chemotherapy, radiotherapy, and postoperative nausea and vomiting.',
   E'Antagonista seletivo dos recetores 5-HT3, presentes perifericamente nos terminais do nervo vago e centralmente na zona de gatilho dos quimiorrecetores da área postrema, bloqueando o reflexo do vómito desencadeado pela serotonina libertada pelas células enterocromafins após quimioterapia.',
   E'Selective 5-HT3 receptor antagonist, with receptors present peripherally on vagal nerve terminals and centrally in the chemoreceptor trigger zone of the area postrema, blocking the vomiting reflex triggered by serotonin released from enterochromaffin cells after chemotherapy.',
   E'• Prevenção de náuseas e vómitos associados a quimioterapia altamente emetogénica (incluindo cisplatina ≥ 50 mg/m²)\n• Prevenção de náuseas e vómitos associados a quimioterapia moderadamente emetogénica\n• Prevenção de náuseas e vómitos associados a radioterapia\n• Náuseas e vómitos pós-operatórios',
   E'• Prevention of nausea and vomiting with highly emetogenic chemotherapy (including cisplatin ≥ 50 mg/m²)\n• Prevention of nausea and vomiting with moderately emetogenic chemotherapy\n• Prevention of nausea and vomiting with radiotherapy\n• Postoperative nausea and vomiting',
   E'• Cefaleias (o mais frequente)\n• Obstipação e diarreia\n• Fadiga e tonturas\n• Prolongamento do intervalo QT e Torsade de Pointes (pós-comercialização)\n• Síndrome serotoninérgica (com fármacos serotoninérgicos)\n• Reações de hipersensibilidade, incluindo anafilaxia e broncospasmo',
   E'• Headache (most common)\n• Constipation and diarrhea\n• Fatigue and dizziness\n• QT interval prolongation and Torsade de Pointes (postmarketing)\n• Serotonin syndrome (with serotonergic drugs)\n• Hypersensitivity reactions, including anaphylaxis and bronchospasm',
   E'• Contraindicado com apomorfina (risco de hipotensão profunda e perda de consciência)\n• Evitar em doentes com QT prolongado congénito ou fatores de risco; monitorizar ECG\n• Vigiar síndrome serotoninérgica com ISRS/IRSN\n• Pode mascarar íleo progressivo e distensão gástrica no pós-operatório',
   E'• Contraindicated with apomorphine (risk of profound hypotension and loss of consciousness)\n• Avoid in congenital long QT or risk factors; monitor ECG\n• Watch for serotonin syndrome with SSRIs/SNRIs\n• May mask progressive ileus and gastric distension postoperatively',
   'Rótulo aprovado DailyMed (Ondansetron Hydrochloride Tablet; setID 14276805-4e99-4bbe-ad76-ffc06eddb38a).',
   'DailyMed approved label (Ondansetron Hydrochloride Tablet; setID 14276805-4e99-4bbe-ad76-ffc06eddb38a).'),
  ('piperacilina_tazobactam',
   E'Associação de penicilina de largo espectro com inibidor de beta-lactamases, indicada em infeções intra-abdominais (apendicite complicada, peritonite), pneumonia nosocomial e outras infeções graves por microrganismos produtores de beta-lactamase, em adultos e crianças ≥ 2 meses.',
   E'Broad-spectrum penicillin plus beta-lactamase inhibitor combination indicated for intra-abdominal infections (complicated appendicitis, peritonitis), nosocomial pneumonia and other serious infections due to beta-lactamase-producing organisms, in adults and children ≥ 2 months.',
   E'A piperacilina é uma penicilina de largo espectro que inibe a síntese da parede celular bacteriana; o tazobactam, inibidor de beta-lactamases, protege a piperacilina da hidrólise pelas beta-lactamases de muitos microrganismos resistentes. O parâmetro farmacodinâmico preditivo de eficácia é o tempo acima da CMI.',
   E'Piperacillin is a broad-spectrum penicillin that inhibits bacterial cell-wall synthesis; tazobactam, a beta-lactamase inhibitor, protects piperacillin from hydrolysis by beta-lactamases of many resistant organisms. The pharmacodynamic parameter predictive of efficacy is time above the MIC.',
   E'• Infeções intra-abdominais (apendicite complicada por rutura ou abcesso, peritonite) por E. coli e grupo Bacteroides fragilis\n• Pneumonia nosocomial (moderada a grave)\n• Infeções graves da pele, urinárias, sépsis e neutropenia febril (conforme indicações aprovadas)',
   E'• Intra-abdominal infections (appendicitis complicated by rupture or abscess, peritonitis) due to E. coli and the Bacteroides fragilis group\n• Nosocomial pneumonia (moderate to severe)\n• Serious skin, urinary infections, septicemia and febrile neutropenia (per approved indications)',
   E'• Diarreia (incluindo colite por Clostridioides difficile)\n• Náuseas, vómitos, obstipação\n• Cefaleias, insónia, febre\n• Erupções cutâneas, prurido, anafilaxia\n• Elevação das transaminases, disfunção renal, trombocitopenia, leucopenia, neutropenia\n• Rabdomiólise (rara) e síndrome de ativação macrofágica (muito rara)',
   E'• Diarrhea (including Clostridioides difficile-associated colitis)\n• Nausea, vomiting, constipation\n• Headache, insomnia, fever\n• Rash, pruritus, anaphylaxis\n• Transaminase elevations, renal dysfunction, thrombocytopenia, leukopenia, neutropenia\n• Rhabdomyolysis (rare) and hemophagocytic lymphohistiocytosis (very rare)',
   E'• Indagar sobre hipersensibilidade a penicilinas, cefalosporinas e inibidores de beta-lactamase\n• Ajustar dose na insuficiência renal\n• Vigiar diarreia associada a Clostridioides difficile, discrasias sanguíneas e sinais de rabdomiólise\n• Monitorizar função renal e eletrólitos (hipocalémia) em tratamentos prolongados',
   E'• Inquire about hypersensitivity to penicillins, cephalosporins and beta-lactamase inhibitors\n• Adjust dose in renal impairment\n• Watch for Clostridioides difficile-associated diarrhea, blood dyscrasias and signs of rhabdomyolysis\n• Monitor renal function and electrolytes (hypokalemia) in prolonged therapy',
   'Rótulo aprovado DailyMed (Piperacillin and Tazobactam Injection; setID 4d3f4b69-b0b9-494f-9cda-4537fa420d47).',
   'DailyMed approved label (Piperacillin and Tazobactam Injection; setID 4d3f4b69-b0b9-494f-9cda-4537fa420d47).'),
  ('pirazinamida',
   E'Fármaco antituberculoso de primeira linha, indicado no tratamento inicial da tuberculose ativa em adultos e crianças, sempre em associação com outros antituberculosos.',
   E'First-line antituberculosis drug indicated for initial treatment of active tuberculosis in adults and children, always in combination with other antituberculous agents.',
   E'Análogo da nicotinamida com atividade bactericida sobre bacilos intracelulares em meio ácido (fagolisossomas), o que complementa a ação de outros antituberculosos. É hidrolisado no fígado no metabolito ativo ácido pirazinoico, essencial para encurtar o esquema inicial da tuberculose.',
   E'Nicotinamide analogue with bactericidal activity against intracellular bacilli in acid medium (phagolysosomes), complementing other antituberculosis drugs. It is hydrolyzed in the liver to the active metabolite pyrazinoic acid, essential to shorten the initial tuberculosis regimen.',
   E'• Tratamento inicial da tuberculose ativa (em associação com isoniazida, rifampicina e etambutol, tipicamente nos primeiros 2 meses do esquema de 6 meses)\n• Componente importante de esquemas individualizados na tuberculose resistente',
   E'• Initial treatment of active tuberculosis (with isoniazid, rifampin and ethambutol, typically the first 2 months of the 6-month regimen)\n• Important component of individualized regimens in drug-resistant tuberculosis',
   E'• Hepatotoxicidade (o principal efeito adverso; relacionada com a dose)\n• Hiperuricemia e gota (artralgias e mialgias ligeiras frequentes)\n• Náuseas, vómitos e anorexia\n• Erupções cutâneas, urticária, fotossensibilidade\n• Trombocitopenia e anemia sideroblástica (raras)\n• Febre e porfiria (raras)',
   E'• Hepatotoxicity (the principal adverse effect; dose related)\n• Hyperuricemia and gout (frequent mild arthralgia and myalgia)\n• Nausea, vomiting and anorexia\n• Rash, urticaria, photosensitivity\n• Thrombocytopenia and sideroblastic anemia (rare)\n• Fever and porphyria (rare)',
   E'• Contraindicado na lesão hepática grave, gota aguda e hipersensibilidade\n• Avaliar ácido úrico sérico e função hepática no início e periodicamente\n• Vigiar hepatotoxicidade em doentes com doença hepática prévia ou risco aumentado\n• Ajustar dose na insuficiência renal',
   E'• Contraindicated in severe hepatic damage, acute gout and hypersensitivity\n• Obtain baseline serum uric acid and liver function tests and monitor periodically\n• Watch for hepatotoxicity in patients with preexisting liver disease or increased risk\n• Adjust dose in renal impairment',
   'Rótulo aprovado DailyMed (Pyrazinamide Tablet, ANI Pharmaceuticals; setID 262d8829-728c-48db-b89b-88d13b87e684).',
   'DailyMed approved label (Pyrazinamide Tablet, ANI Pharmaceuticals; setID 262d8829-728c-48db-b89b-88d13b87e684).'),
  ('poractant_alfa',
   E'Suspensão intratraqueal de surfactante pulmonar natural (extrato de pulmão porcino) indicada no tratamento de resgate da síndrome de dificuldade respiratória do recém-nascido prematuro, reduzindo a mortalidade e os pneumotórax associados.',
   E'Natural pulmonary surfactant suspension (porcine lung extract) for intratracheal administration, indicated for rescue treatment of Respiratory Distress Syndrome in premature infants, reducing associated mortality and pneumothoraces.',
   E'Surfactante pulmonar exógeno que compensa a deficiência de surfactante endógeno nos prematuros, restaurando a atividade de superfície alveolar: reduz a tensão superficial na interface ar-líquido, estabiliza os alvéolos contra o colapso e melhora a oxigenação e a complacência pulmonar.',
   E'Exogenous pulmonary surfactant that compensates for the deficiency of endogenous surfactant in preterm infants, restoring alveolar surface activity: lowers surface tension at the air-liquid interface, stabilizes alveoli against collapse and improves oxygenation and lung compliance.',
   E'• Tratamento de resgate da síndrome de dificuldade respiratória do recém-nascido prematuro',
   E'• Rescue treatment of Respiratory Distress Syndrome in premature infants',
   E'• Bradicardia, hipotensão e dessaturação transitórias durante a administração\n• Apneia e obstrução do tubo endotraqueal\n• Hemorragia pulmonar e enfisema intersticial\n• Alterações transitórias da oxigenação e da complacência pulmonar após instilação',
   E'• Transient bradycardia, hypotension and desaturation during administration\n• Apnea and endotracheal tube obstruction\n• Pulmonary hemorrhage and interstitial emphysema\n• Transient changes in oxygenation and lung compliance after instillation',
   E'• Administrar apenas por pessoal treinado em cuidados, reanimação e estabilização de prematuros\n• Vigiar frequentemente a oxigenação e o suporte ventilatório após a administração\n• Ajustar o suporte ventilatório às alterações respiratórias',
   E'• Administer only by personnel trained in the care, resuscitation and stabilization of preterm infants\n• Monitor oxygenation and ventilatory support frequently after administration\n• Adjust ventilatory support in response to respiratory changes',
   'Rótulo aprovado DailyMed (CUROSURF, Chiesi USA; setID 99bef307-00bd-4379-9f45-ede1380e74d4).',
   'DailyMed approved label (CUROSURF, Chiesi USA; setID 99bef307-00bd-4379-9f45-ede1380e74d4).'),
  ('primaquina',
   E'Antimalárico 8-aminoquinoleína indicado na cura radical (prevenção da recaída) da malária por Plasmodium vivax.',
   E'8-aminoquinoline antimalarial indicated for the radical cure (prevention of relapse) of Plasmodium vivax malaria.',
   E'Antimalárico ativo contra as formas hepáticas dormentes (hipnozoítos) do P. vivax e contra os estádios exoeritrocíticos, prevenindo o desenvolvimento das formas sanguíneas responsáveis pelas recaídas; também ativo contra os gametócitos do P. falciparum. A atividade depende de metabolitos hidroxilados gerados por CYP2D6.',
   E'Antimalarial active against dormant liver forms (hypnozoites) of P. vivax and exoerythrocytic stages, preventing development of the blood forms responsible for relapses; also active against gametocytes of P. falciparum. Activity depends on hydroxylated metabolites generated by CYP2D6.',
   E'• Cura radical (prevenção de recaída) da malária por Plasmodium vivax',
   E'• Radical cure (prevention of relapse) of Plasmodium vivax malaria',
   E'• Náuseas, vómitos, desconforto epigástrico e cólicas abdominais\n• Anemia hemolítica (comum na deficiência de G6PD; pode ser grave ou fatal na deficiência grave)\n• Metemoglobinemia (geralmente < 10%; grave em doentes com deficiência de NADH-metemoglobina redutase)\n• Leucopenia (em doentes com artrite reumatoide ou lúpus)\n• Arritmia cardíaca e prolongamento do QT\n• Tonturas e perturbações visuais',
   E'• Nausea, vomiting, epigastric distress and abdominal cramps\n• Hemolytic anemia (common in G6PD deficiency; may be severe or fatal in severe deficiency)\n• Methemoglobinemia (usually < 10%; severe in NADH methemoglobin reductase deficiency)\n• Leukopenia (in patients with rheumatoid arthritis or lupus)\n• Cardiac arrhythmia and QT prolongation\n• Dizziness and visual disturbances',
   E'• Rastrear a deficiência de G6PD antes de iniciar (contraindicação na deficiência grave)\n• Contraindicado na gravidez e durante a amamentação se o lactente for G6PD deficiente\n• Vigiar sinais de hemólise e metemoglobinemia\n• Ajustar dose nos metabolizadores lentos de CYP2D6 (aumento do risco de hemólise e níveis elevados)',
   E'• Screen for G6PD deficiency before starting (contraindicated in severe deficiency)\n• Contraindicated in pregnancy and breastfeeding if the infant is G6PD deficient\n• Watch for signs of hemolysis and methemoglobinemia\n• Adjust dose in CYP2D6 poor metabolizers (increased hemolysis risk and elevated levels)',
   'Rótulo aprovado DailyMed (Primaquine Phosphate Tablet; setID 3f16166d-678e-51aa-e054-00144ff88e88).',
   'DailyMed approved label (Primaquine Phosphate Tablet; setID 3f16166d-678e-51aa-e054-00144ff88e88).'),
-- ---------------------------------------------------------------------
-- Perfis — B6 (propafenona, salmeterol, tafenoquina, tiotropio, zidovudina)
-- ---------------------------------------------------------------------
  ('propafenona',
   E'Antiarrítmico da classe IC indicado para prolongar o tempo até recorrência da fibrilhação/flutter auricular paroxística e da taquicardia supraventricular paroxística sintomáticas em doentes sem cardiopatia estrutural, e no tratamento de arritmias ventriculares documentadas que ameacem a vida.',
   E'Class 1C antiarrhythmic indicated to prolong time to recurrence of symptomatic paroxysmal atrial fibrillation/flutter and paroxysmal supraventricular tachycardia in patients without structural heart disease, and for treatment of documented life-threatening ventricular arrhythmias.',
   E'Antiarrítmico de classe IC com efeitos anestésicos locais e estabilizadores diretos da membrana miocárdica: reduz a velocidade de subida da fase 0 do potencial de ação, prolonga o período refratário efetivo e reduz a automaticidade. Apresenta também atividade bloqueadora beta (cerca de 1/40 da potência do propranolol por mg).',
   E'Class 1C antiarrhythmic with local anesthetic effects and direct myocardial membrane stabilization: reduces Phase 0 upstroke velocity of the action potential, prolongs the effective refractory period and reduces automaticity. It also has beta-blocking activity (about 1/40 the potency of propranolol per mg).',
   E'• Prolongamento do tempo até recorrência da fibrilhação/flutter auricular paroxística sintomática (sem cardiopatia estrutural)\n• Prolongamento do tempo até recorrência da taquicardia supraventricular paroxística sintomática (sem cardiopatia estrutural)\n• Tratamento de arritmias ventriculares documentadas que ameacem a vida (iniciar em ambiente hospitalar)',
   E'• Prolong time to recurrence of symptomatic paroxysmal atrial fibrillation/flutter (no structural heart disease)\n• Prolong time to recurrence of symptomatic paroxysmal supraventricular tachycardia (no structural heart disease)\n• Treatment of documented life-threatening ventricular arrhythmias (initiate in hospital)',
   E'• Sabor invulgar (disgeusia) — o mais frequente\n• Náuseas e/ou vómitos\n• Tonturas, cefaleias, fadiga, fraqueza\n• Obstipação, diarreia, anorexia\n• Visão turva, tremor, ataxia\n• Efeitos pró-arrítmicos: piora de arritmias, taquicardia de complexos largos, ICC, bradicardia, prolongamento do QT',
   E'• Unusual taste (dysgeusia) — most common\n• Nausea and/or vomiting\n• Dizziness, headache, fatigue, weakness\n• Constipation, diarrhea, anorexia\n• Blurred vision, tremor, ataxia\n• Proarrhythmic effects: worsening of arrhythmias, wide-complex tachycardia, CHF, bradycardia, QT prolongation',
   E'• Contraindicado na insuficiência cardíaca, choque cardiogénico, distúrbios de condução sem pacemaker, síndrome de Brugada conhecida, bradicardia, hipotensão marcada e doença broncospástica grave\n• Avaliar eletrocardiograficamente antes e durante a terapêutica\n• Iniciar o tratamento de arritmias ventriculares em ambiente hospitalar\n• Ajustar dose na insuficiência hepática (biodisponibilidade aumentada)',
   E'• Contraindicated in heart failure, cardiogenic shock, conduction disorders without a pacemaker, known Brugada syndrome, bradycardia, marked hypotension and severe bronchospastic disease\n• Evaluate electrocardiographically before and during therapy\n• Initiate ventricular arrhythmia treatment in hospital\n• Adjust dose in hepatic impairment (increased bioavailability)',
   'Rótulo aprovado DailyMed (Propafenone Hydrochloride Extended-Release Capsule; setID 2ecd6452-ccc3-493f-9a4a-69f0fbf67a42).',
   'DailyMed approved label (Propafenone Hydrochloride Extended-Release Capsule; setID 2ecd6452-ccc3-493f-9a4a-69f0fbf67a42).'),
  ('salmeterol',
   E'Broncodilatador beta-2-agonista de ação prolongada (LABA) indicado no tratamento da asma e prevenção do broncospasmo apenas como terapêutica adjuvante a um corticosteroide inalado (CI), e na manutenção da DPOC.',
   E'Long-acting beta-2 agonist (LABA) bronchodilator indicated for asthma treatment and bronchospasm prevention only as concomitant therapy with an inhaled corticosteroid (ICS), and for maintenance of COPD.',
   E'Beta-2-agonista seletivo de ação prolongada que estimula a adenilciclase intracelular, aumentando o AMP cíclico, o que relaxa o músculo liso brônquico e inibe a libertação de mediadores de hipersensibilidade imediata das células, especialmente mastócitos. Em monoterapia (sem CI) aumenta o risco de morte relacionada com a asma.',
   E'Selective long-acting beta-2 agonist that stimulates intracellular adenyl cyclase, increasing cyclic AMP, which relaxes bronchial smooth muscle and inhibits release of immediate-hypersensitivity mediators from cells, especially mast cells. As monotherapy (without ICS) it increases the risk of asthma-related death.',
   E'• Tratamento da asma e prevenção do broncospasmo, apenas em associação com CI (≥ 4 anos)\n• Manutenção da DPOC\n• (Em associação com fluticasona, conforme formulações combinadas)',
   E'• Asthma treatment and bronchospasm prevention, only with an ICS (≥ 4 years)\n• Maintenance of COPD\n• (With fluticasone, per combination formulations)',
   E'• Tremor, cefaleias, palpitações e taquicardia\n• Cãibras musculares\n• Irritação da faringe e disfonia\n• Broncospasmo paradoxal (raro)\n• Hipocalémia e hiperglicemia (com doses elevadas)\n• Aumento do risco de morte relacionada com a asma em monoterapia',
   E'• Tremor, headache, palpitations and tachycardia\n• Muscle cramps\n• Pharyngeal irritation and dysphonia\n• Paradoxical bronchospasm (rare)\n• Hypokalemia and hyperglycemia (at high doses)\n• Increased risk of asthma-related death as monotherapy',
   E'• Contraindicado sem CI concomitante na asma; nunca usar em monoterapia\n• Não usar como tratamento primário do estado asmático ou de episódios agudos\n• Vigiar sinais de broncospasmo paradoxal\n• Usar com precaução em doentes com doença cardiovascular (tremor, taquicardia)',
   E'• Contraindicated without concomitant ICS in asthma; never as monotherapy\n• Not for primary treatment of status asthmaticus or acute episodes\n• Watch for paradoxical bronchospasm\n• Use with caution in cardiovascular disease (tremor, tachycardia)',
   'Rótulo aprovado DailyMed (SEREVENT DISKUS, salmeterol; setID 1349a04c-2024-42b9-b81d-a7d995716ade).',
   'DailyMed approved label (SEREVENT DISKUS, salmeterol; setID 1349a04c-2024-42b9-b81d-a7d995716ade).'),
  ('tafenoquina',
   E'Antimalárico 8-aminoquinoleína indicado na cura radical (prevenção de recaída) da malária por Plasmodium vivax em doentes ≥ 16 anos a receber cloroquina para a infeção aguda.',
   E'8-aminoquinoline antimalarial indicated for radical cure (prevention of relapse) of Plasmodium vivax malaria in patients ≥ 16 years receiving chloroquine for acute P. vivax infection.',
   E'Antimalárico ativo contra os hipnozoítos hepáticos do P. vivax, prevenindo a recaída, em associação com cloroquina (que elimina as formas sanguíneas agudas). Dose única de 300 mg; doses e esquemas diferentes não estão aprovados.',
   E'Antimalarial active against liver hypnozoites of P. vivax, preventing relapse, in combination with chloroquine (which clears acute blood stages). Single 300 mg dose; other doses or regimens are not approved.',
   E'• Cura radical (prevenção de recaída) da malária por Plasmodium vivax em doentes ≥ 16 anos a receber cloroquina',
   E'• Radical cure (prevention of relapse) of Plasmodium vivax malaria in patients ≥ 16 years receiving chloroquine',
   E'• Anemia hemolítica (risco na deficiência de G6PD)\n• Metemoglobinemia\n• Efeitos psiquiátricos (insónia, sonhos anormais, ansiedade, depressão)\n• Tonturas, cefaleias e náuseas\n• Reações de hipersensibilidade',
   E'• Hemolytic anemia (risk in G6PD deficiency)\n• Methemoglobinemia\n• Psychiatric effects (insomnia, abnormal dreams, anxiety, depression)\n• Dizziness, headache and nausea\n• Hypersensitivity reactions',
   E'• Rastrear G6PD obrigatoriamente antes de prescrever (contraindicação na deficiência ou estado desconhecido)\n• Contraindicado na amamentação se o lactente for G6PD deficiente ou de estado desconhecido\n• Não usar com antimaláricos diferentes da cloroquina (risco de recaída)\n• Não usar no tratamento da malária aguda',
   E'• G6PD testing mandatory before prescribing (contraindicated in deficiency or unknown status)\n• Contraindicated in breastfeeding if the infant is G6PD deficient or of unknown status\n• Do not use with antimalarials other than chloroquine (relapse risk)\n• Not for treatment of acute malaria',
   'Rótulo aprovado DailyMed (KRINTAFEL, tafenoquina succinato; setID 5cf989d5-36f5-4561-a30b-9fcb9deb6b6a).',
   'DailyMed approved label (KRINTAFEL, tafenoquine succinate; setID 5cf989d5-36f5-4561-a30b-9fcb9deb6b6a).'),
  ('tiotropio',
   E'Broncodilatador anticolinérgico de ação prolongada, indicado na manutenção, uma vez por dia, do broncospasmo associado à DPOC (incluindo redução das exacerbações) e na manutenção da asma em doentes ≥ 6 anos.',
   E'Long-acting anticholinergic bronchodilator indicated for once-daily maintenance treatment of bronchospasm associated with COPD (including reduction of exacerbations) and maintenance of asthma in patients ≥ 6 years.',
   E'Agente antimuscarínico de ação prolongada que bloqueia os recetores M3 do músculo liso das vias aéreas, produzindo broncodilatação sustentada (> 24 horas). O antagonismo é competitivo e reversível; o efeito é predominantemente local, no local de inalação.',
   E'Long-acting antimuscarinic agent that blocks M3 receptors of airway smooth muscle, producing sustained bronchodilation (> 24 hours). The antagonism is competitive and reversible; the effect is predominantly site-specific, at the site of inhalation.',
   E'• Manutenção (1x/dia) do broncospasmo na DPOC, incluindo redução das exacerbações\n• Manutenção da asma em doentes ≥ 6 anos',
   E'• Once-daily maintenance of bronchospasm in COPD, including reduction of exacerbations\n• Maintenance of asthma in patients ≥ 6 years',
   E'• Boca seca e faringite\n• Obstipação\n• Tosse e disfonia\n• Reações de hipersensibilidade imediata: urticária, angioedema, prurido, erupções, broncospasmo, anafilaxia\n• Broncospasmo paradoxal\n• Agravamento de glaucoma de ângulo fechado e retenção urinária',
   E'• Dry mouth and pharyngitis\n• Constipation\n• Cough and dysphonia\n• Immediate hypersensitivity reactions: urticaria, angioedema, pruritus, rash, bronchospasm, anaphylaxis\n• Paradoxical bronchospasm\n• Worsening of narrow-angle glaucoma and urinary retention',
   E'• Não usar no alívio do broncospasmo agudo (usar beta-2-agonista de ação rápida)\n• Evitar contacto com os olhos\n• Precaução em doentes com glaucoma de ângulo fechado, hiperplasia prostática ou obstrução do colo vesical\n• Vigiar reações de hipersensibilidade imediata e broncospasmo paradoxal',
   E'• Not for relief of acute bronchospasm (use rapid-acting beta-2-agonist)\n• Avoid contact with the eyes\n• Caution in angle-closure glaucoma, prostatic hyperplasia or bladder-neck obstruction\n• Watch for immediate hypersensitivity reactions and paradoxical bronchospasm',
   'Rótulo aprovado DailyMed (SPIRIVA RESPIMAT, Boehringer Ingelheim; setID 7b656b14-fcaa-2741-f6f0-e0be48971c02).',
   'DailyMed approved label (SPIRIVA RESPIMAT, Boehringer Ingelheim; setID 7b656b14-fcaa-2741-f6f0-e0be48971c02).'),
  ('zidovudina',
   E'Antirretrovírico inibidor nucleósido da transcriptase reversa (INTI), indicado em associação com outros antirretrovíricos no tratamento da infeção por HIV-1 e na prevenção da transmissão materno-fetal do HIV-1.',
   E'Nucleoside reverse transcriptase inhibitor (NRTI) antiretroviral, indicated in combination with other antiretrovirals for treatment of HIV-1 infection and for prevention of maternal-fetal HIV-1 transmission.',
   E'Análogo nucleósido da timidina que inibe a transcriptase reversa viral, interrompendo a síntese do DNA pró-viral. É fosforilado intracelularmente no trifosfato ativo; o metabolito AMT (formado no fígado) contribui para a toxicidade hematológica e mitocondrial.',
   E'Thymidine nucleoside analogue that inhibits viral reverse transcriptase, interrupting proviral DNA synthesis. It is phosphorylated intracellularly to the active triphosphate; the metabolite AMT (formed in the liver) contributes to hematologic and mitochondrial toxicity.',
   E'• Tratamento da infeção por HIV-1 (em associação com outros antirretrovíricos)\n• Prevenção da transmissão materno-fetal do HIV-1 (regime anteparto, intraparto e pós-parto no recém-nascido)',
   E'• Treatment of HIV-1 infection (with other antiretrovirals)\n• Prevention of maternal-fetal HIV-1 transmission (antepartum, intrapartum and postpartum regimen in the neonate)',
   E'• Toxicidade hematológica: neutropenia e anemia (as mais significativas; relacionadas com a reserva medular prévia, dose e duração)\n• Cefaleias, náuseas, fadiga, mal-estar\n• Miopatia sintomática (tratamento prolongado)\n• Acidose láctica e hepatomegalia grave com esteatose (potencialmente fatais)\n• Descompensação hepática em doentes coinfetados com HIV-1 e hepatite C',
   E'• Hematologic toxicity: neutropenia and anemia (most significant; related to pretreatment marrow reserve, dose and duration)\n• Headache, nausea, fatigue, malaise\n• Symptomatic myopathy (prolonged therapy)\n• Lactic acidosis and severe hepatomegaly with steatosis (potentially fatal)\n• Hepatic decompensation in patients co-infected with HIV-1 and hepatitis C',
   E'• Vigiar hemograma (anemia e neutropenia podem surgir às 2–4 e 6–8 semanas, respetivamente)\n• Suspender ou reduzir dose na toxicidade hematológica\n• Vigiar sinais de acidose láctica e esteatose hepática\n• Ajustar dose na insuficiência hepática e renal grave',
   E'• Monitor blood counts (anemia and neutropenia may appear at 2–4 and 6–8 weeks, respectively)\n• Discontinue or reduce dose in hematologic toxicity\n• Watch for lactic acidosis and hepatic steatosis\n• Adjust dose in severe hepatic and renal impairment',
   'Rótulo aprovado DailyMed (RETROVIR, zidovudina; setID e816e8f5-1e50-4f49-8bea-92da0121d26e).',
   'DailyMed approved label (RETROVIR, zidovudine; setID e816e8f5-1e50-4f49-8bea-92da0121d26e)')
) AS v(slug, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
        indications_pt, indications_en, side_effects_pt, side_effects_en,
        precautions_pt, precautions_en, source_pt, source_en)
JOIN public.drugs d ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;

-- =====================================================================
-- Farmacologia (drug_pharmacology, padrão 088/091/092)
-- =====================================================================

INSERT INTO public.drug_pharmacology
  (drug_id, pharmacodynamics_pt, pharmacodynamics_en, mechanism_pt, mechanism_en,
   metabolism_pt, metabolism_en, absorption_pt, absorption_en,
   half_life_pt, half_life_en, source_pt, source_en)
SELECT d.id, v.pharmacodynamics_pt, v.pharmacodynamics_en, v.mechanism_pt, v.mechanism_en,
       v.metabolism_pt, v.metabolism_en, v.absorption_pt, v.absorption_en,
       v.half_life_pt, v.half_life_en, v.source_pt, v.source_en
FROM (VALUES
-- ---------------------------------------------------------------------
-- Farmacologia — F1 (acetilcisteina, ácido ursodesoxicolico, artesunato,
-- benzilpenicilina benzatina, butilbrometo de hioscina)
-- ---------------------------------------------------------------------
  ('acetilcisteina',
   E'Antioxidante e mucolítico: os grupos tiol livres quebram as pontes dissulfureto das glicoproteínas do muco (ação mucolítica direta); o efeito antioxidante protege as células das espécies reativas de oxigénio. Como antídoto do paracetamol, restaura a glutatião hepática e conjuga diretamente o metabolito reativo NAPQI.',
   E'Antioxidant and mucolytic: free thiol groups break disulfide bonds of mucus glycoproteins (direct mucolytic action); the antioxidant effect protects cells from reactive oxygen species. As a paracetamol antidote, it restores hepatic glutathione and directly conjugates the reactive metabolite NAPQI.',
   E'Por via inalatória, reduz a viscosidade das secreções brônquicas por rutura das pontes dissulfureto. Na intoxicação por paracetamol, o principal mecanismo é a reposição dos depósitos de glutatião hepático e a conjugação direta do metabolito tóxico, evitando a lesão hepatocelular.',
   E'By inhalation, reduces bronchial secretion viscosity by breaking disulfide bonds. In paracetamol poisoning, the main mechanism is replenishment of hepatic glutathione stores and direct conjugation of the toxic metabolite, preventing hepatocellular injury.',
   E'Rapidamente absorvido após dose oral terapêutica (pico em 30–60 min); sofre extenso efeito de primeira passagem hepático e intestinal. O principal metabolito é a cisteína, precursora da glutatião; os conjugados sulfato e glucuronido são excretados na urina.',
   E'Rapidly absorbed after a therapeutic oral dose (peak at 30–60 min); undergoes extensive hepatic and intestinal first-pass metabolism. The main metabolite is cysteine, a glutathione precursor; sulfate and glucuronide conjugates are excreted in the urine.',
   E'Bem absorvido por via oral e inalatória. Após dose terapêutica oral, os picos plasmáticos ocorrem entre 30 e 60 minutos; após sobredosagem, habitualmente dentro de 4 horas.',
   E'Well absorbed orally and by inhalation. After a therapeutic oral dose, plasma peaks occur between 30 and 60 minutes; after overdose, usually within 4 hours.',
   E'Semivida plasmática curta do composto intacto (a acetilcisteína é rapidamente metabolizada); a cisteína e os conjugados mantêm níveis sustentados durante várias horas, sustentando o efeito de reposição de glutatião no tratamento da intoxicação.',
   E'Short plasma half-life of the intact compound (rapidly metabolized); cysteine and conjugates maintain sustained levels for several hours, sustaining the glutathione-replenishing effect in poisoning treatment.',
   'Rótulo aprovado DailyMed (Acetylcysteine Solution, Hospira; setID 5558a5f5-e821-473b-7d8a-5d33d09f0586).',
   'DailyMed approved label (Acetylcysteine Solution, Hospira; setID 5558a5f5-e821-473b-7d8a-5d33d09f0586).'),
  ('acido_ursodesoxicolico',
   E'Ácido biliar hidrofílico que reduz a saturação de colesterol da bílis: diminui a secreção hepática e a absorção intestinal de colesterol, formando uma fase líquida-cristalina que dissolve lentamente os cálculos de colesterol. Exerce ainda efeito citoprotetor e imunomodulador na colangite biliar primária.',
   E'Hydrophilic bile acid that reduces biliary cholesterol saturation: decreases hepatic cholesterol secretion and intestinal absorption, forming a liquid-crystalline phase that slowly dissolves cholesterol gallstones. It also exerts cytoprotective and immunomodulatory effects in primary biliary cholangitis.',
   E'Reduz a saturação de colesterol da bílis por diminuição da secreção hepática de colesterol e da absorção intestinal, promovendo a dissolução progressiva dos cálculos de colesterol; a ação decorre no fígado, bílis e lúmen intestinal.',
   E'Reduces biliary cholesterol saturation by decreasing hepatic cholesterol secretion and intestinal absorption, promoting progressive dissolution of cholesterol gallstones; the action takes place in the liver, bile and gut lumen.',
   E'Cerca de 90% da dose oral é absorvida no intestino delgado; após absorção, é extraída eficientemente do sangue portal pelo fígado (grande efeito de primeira passagem), conjugada com glicina ou taurina e secretada nos canais biliares. Sofre circulação entero-hepática; uma pequena proporção é degradada por bactérias intestinais.',
   E'About 90% of an oral dose is absorbed in the small bowel; after absorption it is efficiently extracted from portal blood by the liver (large first-pass effect), conjugated with glycine or taurine and secreted into the hepatic bile ducts. Undergoes enterohepatic circulation; a small proportion is degraded by intestinal bacteria.',
   E'Bem absorvido no intestino delgado (~90%); pequenas quantidades aparecem na circulação sistémica e quantidades muito pequenas são excretadas na urina.',
   E'Well absorbed in the small bowel (~90%); small quantities appear in the systemic circulation and very small amounts are excreted in urine.',
   E'Devido à circulação entero-hepática, o fármaco permanece no compartimento biliar durante o ciclo digestivo; a semivida sistémica é curta, mas a exposição hepática e biliar é prolongada.',
   E'Owing to enterohepatic circulation, the drug remains in the biliary compartment during the digestive cycle; the systemic half-life is short, but hepatic and biliary exposure is prolonged.',
   'Rótulo aprovado DailyMed (Ursodiol Capsule, Strides Pharma; setID 9a6c1928-2d52-4d9a-8e83-f71892a7e98d).',
   'DailyMed approved label (Ursodiol Capsule, Strides Pharma; setID 9a6c1928-2d52-4d9a-8e83-f71892a7e98d).'),
  ('artesunato',
   E'Pró-fármaco da artemisinina com ação rápida sobre as formas eritrocitárias do Plasmodium: o endoperóxido é ativado pelo ferro do heme parasitário, gerando radicais livres que danificam proteínas e membranas do parasita. Reduz rapidamente a parasitemia, incluindo nas formas graves da malária.',
   E'Artemisinin prodrug with rapid action on erythrocytic Plasmodium forms: the endoperoxide is activated by parasitic heme iron, generating free radicals that damage parasite proteins and membranes. It rapidly reduces parasitemia, including in severe malaria.',
   E'Após administração intravenosa, o artesunato é rapidamente hidrolisado no metabolito ativo dihidroartemisinina (DHA), um endoperóxido que, ativado pelo ferro intraparasitário, gera espécies reativas que lesam as proteínas do parasita e impedem a sua multiplicação.',
   E'After intravenous administration, artesunate is rapidly hydrolyzed to the active metabolite dihydroartemisinin (DHA), an endoperoxide that, activated by intraparasitic iron, generates reactive species that damage parasite proteins and prevent multiplication.',
   E'O artesunato é extensamente metabolizado por hidrólise (esterases plasmáticas e hepáticas) em DHA, o principal metabolito ativo; o DHA é depois glucuronoconjugado e excretado por via biliar e renal.',
   E'Artesunate is extensively metabolized by hydrolysis (plasma and hepatic esterases) to DHA, the main active metabolite; DHA is then glucuronidated and excreted in bile and urine.',
   E'Administrado por via intravenosa; o artesunato é rapidamente convertido em DHA (semivida de conversão de minutos), atingindo concentrações terapêuticas de DHA de forma imediata.',
   E'Administered intravenously; artesunate is rapidly converted to DHA (conversion half-life of minutes), reaching therapeutic DHA concentrations immediately.',
   E'Artesunato: semivida de eliminação de 3–29 min; DHA: semivida de 40–95 min (SmPC-padrão WHO, MA152).',
   E'Artesunate: elimination half-life 3–29 min; DHA: 40–95 min (WHO model SmPC, MA152).',
   'SmPC-padrão WHO-prequalificado (MA152) e EMA (Artesunate Amivas).',
   'WHO-prequalified model SmPC (MA152) and EMA (Artesunate Amivas).'),
  ('benzilpenicilina_benzatina',
   E'Antibiótico bactericida de ação prolongada: a baixa solubilidade do sal de benzatina assegura libertação lenta a partir do depósito intramuscular, mantendo níveis séricos baixos mas eficazes durante dias a semanas, o que permite esquemas terapêuticos com intervalos longos (ex.: sífilis).',
   E'Bactericidal antibiotic with prolonged action: the low solubility of the benzathine salt ensures slow release from the intramuscular depot, maintaining low but effective serum levels for days to weeks, allowing long-interval regimens (e.g. syphilis).',
   E'Inibe a síntese da parede celular bacteriana na fase de multiplicação ativa. A hidrólise do sal de benzatina liberta penicilina G de forma lenta e contínua, mantendo níveis séricos prolongados.',
   E'Inhibits bacterial cell-wall synthesis during active multiplication. Hydrolysis of the benzathine salt releases penicillin G slowly and continuously, maintaining prolonged serum levels.',
   E'Hidrolisado a penicilina G; aproximadamente 60% da penicilina G liga-se às proteínas séricas. Distribui-se amplamente pelos tecidos, com níveis mais altos no rim, fígado, pele e intestino; penetra pouco no LCR com meninges normais.',
   E'Hydrolyzed to penicillin G; approximately 60% of penicillin G is serum-protein bound. Widely distributed in tissues, with highest levels in kidney, liver, skin and intestines; poor CSF penetration with normal meninges.',
   E'Libertação lenta a partir do local de injeção IM: 300 000 U mantêm níveis de 0,03–0,05 U/mL por 4–5 dias; 1 200 000 U mantêm níveis detetáveis até 4 semanas.',
   E'Slow release from the IM injection site: 300,000 U maintain levels of 0.03–0.05 U/mL for 4–5 days; 1,200,000 U maintain detectable levels for up to 4 weeks.',
   E'Semivida de eliminação prolongada efetiva de dias a semanas, dependente da dose administrada (níveis detetáveis até 4 semanas após 1,2 milhões de unidades).',
   E'Effective elimination half-life of days to weeks, dose dependent (detectable levels up to 4 weeks after 1.2 million units).',
   'Rótulo aprovado DailyMed (Bicillin L-A, Pfizer; setID 012d46f1-d0a0-4676-a879-cd320297ab16).',
   'DailyMed approved label (Bicillin L-A, Pfizer; setID 012d46f1-d0a0-4676-a879-cd320297ab16).'),
  ('butilbrometo_hioscina',
   E'Anticolinérgico (antimuscarínico) que bloqueia os recetores muscarínicos da musculatura lisa visceral, aliviando o espasmo gastrointestinal, biliar e urinário. Composto de amónio quaternário, não atravessa a barreira hematoencefálica, pelo que os efeitos centrais são mínimos.',
   E'Anticholinergic (antimuscarinic) that blocks muscarinic receptors of visceral smooth muscle, relieving gastrointestinal, biliary and urinary spasm. As a quaternary ammonium compound it does not cross the blood-brain barrier, so central effects are minimal.',
   E'Antagonismo competitivo dos recetores muscarínicos M2/M3 da musculatura lisa, com redução do espasmo e da dor associada; a elevada polaridade limita a absorção e a passagem central.',
   E'Competitive antagonism of M2/M3 muscarinic receptors of smooth muscle, reducing spasm and associated pain; high polarity limits absorption and central passage.',
   E'Parcialmente metabolizado; a eliminação é renal (~50%) e fecal. O efeito espasmolítico é predominantemente local no trato gastrointestinal.',
   E'Partially metabolized; elimination is renal (~50%) and fecal. The spasmolytic effect is predominantly local in the GI tract.',
   E'Composto de amónio quaternário altamente polar: absorção oral ~8% e biodisponibilidade sistémica < 1%; não atravessa a barreira hematoencefálica.',
   E'Highly polar quaternary ammonium compound: oral absorption ~8% and systemic bioavailability < 1%; does not cross the blood-brain barrier.',
   E'Semivida de eliminação ~5 h (dados do SmPC Buscopan).',
   E'Elimination half-life ~5 h (Buscopan SmPC data).',
   'SmPC Buscopan (EMC-UK, product 1775).',
   'Buscopan SmPC (EMC-UK, product 1775).'),
-- ---------------------------------------------------------------------
-- Farmacologia — F2 (cefalexina, cefazolina, cefepima, cefotaxima, cefuroxima)
-- ---------------------------------------------------------------------
  ('cefalexina',
   E'Antibiótico bactericida que inibe a síntese da parede celular bacteriana (cefalosporina de 1.ª geração). O parâmetro farmacodinâmico preditivo de eficácia é o tempo durante o qual a concentração livre excede a CMI do microrganismo.',
   E'Bactericidal antibiotic that inhibits bacterial cell-wall synthesis (first-generation cephalosporin). The pharmacodynamic parameter predictive of efficacy is the time during which the free concentration exceeds the MIC of the organism.',
   E'Inibição da síntese da parede celular por ligação às proteínas de ligação às penicilinas (PBP), com lise bacteriana na fase de multiplicação ativa.',
   E'Inhibition of cell-wall synthesis by binding to penicillin-binding proteins (PBPs), with bacterial lysis during active multiplication.',
   E'Excretada na urina por filtração glomerular e secreção tubular; mais de 90% da dose é eliminada inalterada na urina em 8 horas.',
   E'Excreted in urine by glomerular filtration and tubular secretion; over 90% of the dose is eliminated unchanged in urine within 8 hours.',
   E'Estável em meio ácido (pode ser administrada independentemente das refeições); picos séricos de ~9, 18 e 32 mcg/mL 1 hora após doses de 250, 500 e 1000 mg. Ligação às proteínas plasmáticas de 10–15%.',
   E'Acid stable (may be given without regard to meals); peak serum levels of ~9, 18 and 32 mcg/mL 1 hour after 250, 500 and 1000 mg doses. Plasma protein binding 10–15%.',
   E'Semivida de eliminação ~1 h em doentes com função renal normal (os níveis séricos permanecem detetáveis até 6 horas após a dose).',
   E'Elimination half-life ~1 h in patients with normal renal function (serum levels remain detectable up to 6 hours after dosing).',
   'Rótulo aprovado DailyMed (Cephalexin Capsule; setID b73593ce-0b1f-4371-bae1-140742de3b42).',
   'DailyMed approved label (Cephalexin Capsule; setID b73593ce-0b1f-4371-bae1-140742de3b42).'),
  ('cefazolina',
   E'Antibiótico bactericida (cefalosporina de 1.ª geração) que inibe a síntese da parede celular bacteriana; utilizada frequentemente em profilaxia cirúrgica pela sua boa penetração nos tecidos e semivida adequada.',
   E'Bactericidal antibiotic (first-generation cephalosporin) that inhibits bacterial cell-wall synthesis; commonly used in surgical prophylaxis owing to good tissue penetration and adequate half-life.',
   E'Inibição da síntese da parede celular por ligação às proteínas de ligação às penicilinas (PBP), com atividade bactericida contra estafilococos (incluindo produtores de penicilinase) e estreptococos.',
   E'Inhibition of cell-wall synthesis by binding to penicillin-binding proteins (PBPs), with bactericidal activity against staphylococci (including penicillinase producers) and streptococci.',
   E'Excretada principalmente inalterada na urina (70–80% em 24 horas); metabolismo hepático mínimo.',
   E'Excreted mainly unchanged in urine (70–80% within 24 hours); minimal hepatic metabolism.',
   E'Após administração IV de 1 g, picos séricos de ~185 mcg/mL; concentrações de ~4 mcg/mL às 8 horas. Atinge níveis elevados na bílis em doentes sem obstrução biliar.',
   E'After IV administration of 1 g, peak serum levels of ~185 mcg/mL; concentrations of ~4 mcg/mL at 8 hours. Reaches high bile levels in patients without biliary obstruction.',
   E'Semivida sérica ~1,8 h após administração IV.',
   E'Serum half-life ~1.8 h after IV administration.',
   'Rótulo aprovado DailyMed (Cefazolin Injection, WG Critical Care; setID 1999084a-124c-45f9-801f-416a1b942c96).',
   'DailyMed approved label (Cefazolin Injection, WG Critical Care; setID 1999084a-124c-45f9-801f-416a1b942c96).'),
  ('cefepima',
   E'Cefalosporina de 4.ª geração: a eficácia correlaciona-se com o tempo acima da CMI (parâmetro farmacodinâmico validado em modelos animais). Espectro alargado incluindo Pseudomonas aeruginosa e Enterobacter spp.',
   E'Fourth-generation cephalosporin: efficacy correlates with time above the MIC (pharmacodynamic parameter validated in animal models). Extended spectrum including Pseudomonas aeruginosa and Enterobacter spp.',
   E'Inibição da síntese da parede celular por ligação às PBP; é estável à hidrólise pela maioria das beta-lactamases cromossómicas e plasmidiais, incluindo muitas AmpC.',
   E'Inhibition of cell-wall synthesis by binding to PBPs; stable to hydrolysis by most chromosomal and plasmidial beta-lactamases, including many AmpC.',
   E'Eliminação predominantemente renal: semivida média de 2 (±0,3) h e clearance total de 120 (±8) mL/min em voluntários saudáveis; farmacocinética linear entre 250 mg e 2 g, sem acumulação com doses repetidas.',
   E'Predominantly renal elimination: mean half-life of 2 (±0.3) h and total clearance of 120 (±8) mL/min in healthy volunteers; linear pharmacokinetics between 250 mg and 2 g, with no accumulation on repeated dosing.',
   E'Administração exclusivamente parentérica (IV/IM); a absorção IM é completa, com biodisponibilidade de ~82% após dose IM de 50 mg/kg em crianças.',
   E'Exclusively parenteral administration (IV/IM); IM absorption is complete, with ~82% bioavailability after a 50 mg/kg IM dose in children.',
   E'Semivida média de eliminação de 2 (±0,3) h; prolonga-se para ~13 h nos doentes em hemodiálise.',
   E'Mean elimination half-life of 2 (±0.3) h; prolonged to ~13 h in patients on hemodialysis.',
   'Rótulo aprovado DailyMed (Cefepime Injection, WG Critical Care; setID 5fd857e5-591f-44ca-80cf-fd903660b03c).',
   'DailyMed approved label (Cefepime Injection, WG Critical Care; setID 5fd857e5-591f-44ca-80cf-fd903660b03c).'),
  ('cefotaxima',
   E'Cefalosporina de 3.ª geração: o tempo acima da CMI correlaciona-se com a eficácia. Boa atividade contra Gram-negativos (incluindo H. influenzae produtor de beta-lactamase) e boa penetração no LCR com meninges inflamadas.',
   E'Third-generation cephalosporin: time above the MIC correlates with efficacy. Good activity against Gram-negatives (including beta-lactamase-producing H. influenzae) and good CSF penetration with inflamed meninges.',
   E'Inibição da síntese da parede celular por ligação às PBP; estável à maioria das beta-lactamases plasmidiais e cromossómicas.',
   E'Inhibition of cell-wall synthesis by binding to PBPs; stable to most plasmidial and chromosomal beta-lactamases.',
   E'~60% da dose é recuperada na urina nas primeiras 6 horas; 20–36% excretada inalterada e 15–25% como desacetilcefotaxima (metabolito ativo). O metabolito desacetil contribui para a atividade bactericida.',
   E'~60% of the dose is recovered in urine within the first 6 hours; 20–36% excreted unchanged and 15–25% as desacetylcefotaxime (active metabolite). The desacetyl metabolite contributes to bactericidal activity.',
   E'Após administração IM de 500 mg ou 1 g, picos séricos de 11,7 e 20,5 mcg/mL em ~30 min; após IV de 1 g, ~101,7 mcg/mL. Sem acumulação com infusões repetidas de 1 g a cada 6 h durante 14 dias.',
   E'After IM administration of 500 mg or 1 g, peak serum levels of 11.7 and 20.5 mcg/mL within ~30 min; after IV of 1 g, ~101.7 mcg/mL. No accumulation with repeated 1 g infusions every 6 h for 14 days.',
   E'Semivida de eliminação ~1 h.',
   E'Elimination half-life ~1 h.',
   'Rótulo aprovado DailyMed (Cefotaxime Injection; setID 8efe3bd0-c43a-2bd6-e053-2a95a90a92fa).',
   'DailyMed approved label (Cefotaxime Injection; setID 8efe3bd0-c43a-2bd6-e053-2a95a90a92fa).'),
  ('cefuroxima',
   E'Cefalosporina de 2.ª geração: o tempo acima da CMI é o parâmetro preditivo de eficácia. Espectro alargado a Gram-negativos, incluindo cepas de H. influenzae e M. catarrhalis produtoras de beta-lactamase.',
   E'Second-generation cephalosporin: time above the MIC is the predictive efficacy parameter. Extended Gram-negative spectrum, including beta-lactamase-producing strains of H. influenzae and M. catarrhalis.',
   E'Inibição da síntese da parede celular por ligação às PBP; o axetil (profármaco oral) é hidrolisado por esterases da mucosa intestinal e do sangue a cefuroxima ativa.',
   E'Inhibition of cell-wall synthesis by binding to PBPs; axetil (oral prodrug) is hydrolyzed by intestinal mucosa and blood esterases to active cefuroxime.',
   E'Excreção renal predominantemente inalterada; a semivida de eliminação prolonga-se com a gravidade da insuficiência renal (~3,4 h na insuficiência moderada/grave).',
   E'Predominantly renal excretion unchanged; elimination half-life prolongs with severity of renal impairment (~3.4 h in moderate/severe impairment).',
   E'A absorção oral é aumentada com alimentos (biodisponibilidade de 37% em jejum a 52% com alimentos); picos plasmáticos em 2–3 h; semivida de eliminação ~1,2 h.',
   E'Oral absorption is enhanced with food (bioavailability from 37% fasting to 52% fed); plasma peaks at 2–3 h; elimination half-life ~1.2 h.',
   E'Semivida média de eliminação ~1,2–1,3 h (comprimidos de 125–1000 mg).',
   E'Mean elimination half-life ~1.2–1.3 h (125–1000 mg tablets).',
   'Rótulo aprovado DailyMed (Cefuroxime Axetil Tablet; setID 76cec54f-d167-4298-951b-5411a3c47f4a).',
   'DailyMed approved label (Cefuroxime Axetil Tablet; setID 76cec54f-d167-4298-951b-5411a3c47f4a).'),
-- ---------------------------------------------------------------------
-- Farmacologia — F3 (etilefrina, famotidina, fenoximetilpenicilina, filgrastim, fondaparinux)
-- ---------------------------------------------------------------------
  ('etilefrina',
   E'Simpaticomimético com ação direta sobre recetores alfa e beta-adrenérgicos: aumenta a resistência vascular periférica (efeito alfa) e a contratilidade e frequência cardíacas (efeito beta), elevando a pressão arterial. O efeito pressor é rápido e de curta duração.',
   E'Sympathomimetic with direct action on alpha and beta-adrenergic receptors: increases peripheral vascular resistance (alpha effect) and cardiac contractility and rate (beta effect), raising blood pressure. The pressor effect is rapid and short-lived.',
   E'Agonismo direto dos recetores adrenérgicos, com predomínio do efeito vasopressor; a resposta farmacodinâmica correlaciona-se com a quantidade de fármaco no compartimento central.',
   E'Direct agonism of adrenergic receptors, with predominant vasopressor effect; the pharmacodynamic response correlates with the amount of drug in the central compartment.',
   E'O principal metabolito é o sulfato fenólico (conjugação); uma proporção muito pequena é excretada como ácido hidroximandélico. ~80% da dose é excretada na urina após administração oral ou IV.',
   E'The main metabolite is the phenolic sulfate (conjugation); a very small proportion is excreted as hydroxymandelic acid. ~80% of the dose is excreted in urine after oral or IV administration.',
   E'Absorção entérica completa (~80% da dose recuperada na urina); o efeito de primeira passagem é extenso, resultando numa biodisponibilidade do fármaco inalterado de ~55%.',
   E'Complete enteral absorption (~80% of the dose recovered in urine); extensive first-pass effect results in ~55% bioavailability of unchanged drug.',
   E'Semivida predominante ~2 h, compatível com modelo bicompartimental; volume de distribuição (Vd beta) de ~160 L.',
   E'Predominant half-life ~2 h, consistent with a two-compartment model; volume of distribution (Vd beta) of ~160 L.',
   'Hengstmann JH 1975 (PMID 9300) — disposition fisiológica da etilefrina no homem.',
   'Hengstmann JH 1975 (PMID 9300) — physiological disposition of etilefrine in man.'),
  ('famotidina',
   E'Antagonista H2 que inibe a secreção ácida gástrica basal e noturna, bem como a estimulada por alimento e pentagastrina. Inibição de 86% (20 mg) e 94% (40 mg) da secreção ácida noturna, durante pelo menos 10 horas.',
   E'H2 antagonist that inhibits basal and nocturnal gastric acid secretion, as well as food- and pentagastrin-stimulated secretion. Inhibition of 86% (20 mg) and 94% (40 mg) of nocturnal acid secretion, for at least 10 hours.',
   E'Inibição competitiva dos recetores H2 da histamina nas células parietais, suprimindo a concentração e o volume de secreção ácida gástrica; a secreção de pepsina varia proporcionalmente ao volume.',
   E'Competitive inhibition of histamine H2 receptors on parietal cells, suppressing acid concentration and volume of gastric secretion; pepsin secretion varies proportionally to volume.',
   E'Metabolismo de primeira passagem mínimo; 25–30% da dose oral é recuperada inalterada na urina. O único metabolito identificado no homem é o S-óxido.',
   E'Minimal first-pass metabolism; 25–30% of an oral dose is recovered unchanged in urine. The only metabolite identified in humans is the S-oxide.',
   E'Absorção incompleta (biodisponibilidade oral de 40–45%); picos plasmáticos em 1–3 horas; ligação às proteínas plasmáticas de 15–20%. A biodisponibilidade pode aumentar ligeiramente com alimentos e diminuir com antiácidos.',
   E'Incomplete absorption (oral bioavailability 40–45%); plasma peaks at 1–3 hours; plasma protein binding 15–20%. Bioavailability may slightly increase with food and decrease with antacids.',
   E'Semivida de eliminação de 2,5–3,5 h; eliminada por vias renal (65–70%) e metabólica (30–35%).',
   E'Elimination half-life of 2.5–3.5 h; eliminated by renal (65–70%) and metabolic (30–35%) routes.',
   'Rótulo aprovado DailyMed (Ibuprofen and Famotidine Tablet, Doctor Reddy; setID 9f5de6af-e555-4efd-a3ed-b72c34c051b6).',
   'DailyMed approved label (Ibuprofen and Famotidine Tablet, Doctor Reddy; setID 9f5de6af-e555-4efd-a3ed-b72c34c051b6).'),
  ('fenoximetilpenicilina',
   E'Antibiótico bactericida que exerce a sua ação contra microrganismos sensíveis na fase de multiplicação ativa, por inibição da biossíntese do mucopeptídeo da parede celular.',
   E'Bactericidal antibiotic that acts against sensitive microorganisms during active multiplication by inhibiting biosynthesis of cell-wall mucopeptide.',
   E'Inibição da síntese da parede celular bacteriana (ligação às PBP); inativo contra bactérias produtoras de penicilinase (muitas estirpes de estafilococos).',
   E'Inhibition of bacterial cell-wall synthesis (PBP binding); inactive against penicillinase-producing bacteria (many staphylococcal strains).',
   E'Excreção renal rápida; apenas ~25% da dose oral é recuperada na urina, refletindo a absorção parcial.',
   E'Rapid renal excretion; only ~25% of the oral dose is recovered in urine, reflecting partial absorption.',
   E'O sal potássico da penicilina V é mais resistente à inativação pelo ácido gástrico que a penicilina G; pode ser administrado com as refeições, embora os níveis sanguíneos sejam ligeiramente mais altos em jejum. Níveis médios 2–5x superiores aos da penicilina G oral.',
   E'Penicillin V potassium is more resistant to gastric-acid inactivation than penicillin G; it may be given with meals, though blood levels are slightly higher when fasting. Average levels 2–5x higher than oral penicillin G.',
   E'Semivida curta (~30 min); exige administração repetida ao longo do dia para manter níveis eficazes.',
   E'Short half-life (~30 min); requires repeated administration throughout the day to maintain effective levels.',
   'Rótulo aprovado DailyMed (Penicillin V Potassium Tablet; setID 64ac283c-fe6a-49f0-ae85-90ab98e38272).',
   'DailyMed approved label (Penicillin V Potassium Tablet; setID 64ac283c-fe6a-49f0-ae85-90ab98e38272).'),
  ('filgrastim',
   E'G-CSF que regula a produção de neutrófilos na medula óssea, afetando a proliferação, diferenciação e funções finais dos progenitores neutrofílicos (incluindo fagocitose aumentada e priming do burst respiratório). O efeito é específico da linhagem neutrofílica.',
   E'G-CSF that regulates neutrophil production in the bone marrow, affecting proliferation, differentiation and selected end-cell functions of neutrophil progenitors (including enhanced phagocytosis and respiratory-burst priming). The effect is specific to the neutrophil lineage.',
   E'Ligação a recetores específicos de G-CSF nas células progenitoras hematopoiéticas, estimulando a proliferação, o compromisso de diferenciação e a ativação funcional dos neutrófilos.',
   E'Binding to specific G-CSF receptors on hematopoietic progenitor cells, stimulating proliferation, differentiation commitment and functional activation of neutrophils.',
   E'Clearance renal predominante (o fármaco é eliminado sobretudo por via renal).',
   E'Predominantly renal clearance (eliminated mainly by the renal route).',
   E'Biodisponibilidade de 60–70% após administração subcutânea; picos séricos 2–8 h após a dose.',
   E'Bioavailability of 60–70% after subcutaneous administration; serum peaks 2–8 h after dosing.',
   E'Semivida de eliminação ~3,5 h (aproximadamente 3,5 h após administração subcutânea).',
   E'Elimination half-life ~3.5 h (approximately 3.5 h after subcutaneous administration).',
   'Rótulo aprovado DailyMed (NEUPOGEN, Amgen; setID 97cc73cc-b5b7-458a-a933-77b00523e193).',
   'DailyMed approved label (NEUPOGEN, Amgen; setID 97cc73cc-b5b7-458a-a933-77b00523e193).'),
  ('fondaparinux',
   E'A atividade antitrombótica resulta da inibição seletiva do fator Xa mediada pela antitrombina III: ao ligar-se seletivamente à ATIII, potencia (~300x) a neutralização do fator Xa, interrompendo a cascata da coagulação e inibindo a formação de trombina. Não inativa a trombina nem afeta a função plaquetária.',
   E'Antithrombotic activity results from antithrombin III-mediated selective inhibition of factor Xa: by selectively binding ATIII, it potentiates (~300-fold) the neutralization of factor Xa, interrupting the coagulation cascade and inhibiting thrombin formation. It does not inactivate thrombin nor affect platelet function.',
   E'Pentassacarídeo sintético que se liga seletivamente à antitrombina III (ATIII), potenciando a neutralização do fator Xa; a farmacodinâmica é monitorizada por atividade anti-Xa calibrada com fondaparinux.',
   E'Synthetic pentasaccharide that selectively binds antithrombin III (ATIII), potentiating factor Xa neutralization; pharmacodynamics are monitored by anti-Xa activity calibrated with fondaparinux.',
   E'Excreção renal predominante do fármaco inalterado; sem metabolismo hepático significativo.',
   E'Predominantly renal excretion of unchanged drug; no significant hepatic metabolism.',
   E'Biodisponibilidade absoluta de 100% após administração subcutânea; picos plasmáticos em ~2–3 horas após a dose.',
   E'Absolute bioavailability of 100% after subcutaneous administration; plasma peaks ~2–3 hours after dosing.',
   E'Semivida de eliminação de 17–21 horas (permitindo administração uma vez por dia).',
   E'Elimination half-life of 17–21 hours (allowing once-daily administration).',
   'Rótulo aprovado DailyMed (Fondaparinux Sodium Injection, Zydus; setID dffbf7c9-495e-4a33-ac76-57b52f014fc2).',
   'DailyMed approved label (Fondaparinux Sodium Injection, Zydus; setID dffbf7c9-495e-4a33-ac76-57b52f014fc2).'),
-- ---------------------------------------------------------------------
-- Farmacologia — F4 (ipratropio, memantina, midodrina, montelukast, nistatina)
-- ---------------------------------------------------------------------
  ('ipratropio',
   E'Broncodilatação predominantemente local e específica do local de inalação: o antagonismo da acetilcolina nos recetores muscarínicos do músculo liso brônquico impede o aumento do GMP cíclico intracelular, revertendo a broncoconstrição colinérgica.',
   E'Bronchodilation predominantly local and site-specific: antagonism of acetylcholine at muscarinic receptors of bronchial smooth muscle prevents the rise of intracellular cyclic GMP, reversing cholinergic bronchoconstriction.',
   E'Antagonismo competitivo da acetilcolina nos recetores muscarínicos brônquicos (ação parassimpatolítica), bloqueando os reflexos mediados pelo vago.',
   E'Competitive antagonism of acetylcholine at bronchial muscarinic receptors (parasympatholytic action), blocking vagally mediated reflexes.',
   E'Parcialmente metabolizado; a excreção é predominantemente fecal (grande parte da dose inalada é deglutida e não absorvida).',
   E'Partially metabolized; excretion is predominantly fecal (much of the inhaled dose is swallowed and not absorbed).',
   E'Após nebulização de 2 mg, apenas ~7% da dose atinge a circulação sistémica (a partir do pulmão ou do trato gastrointestinal). Ligação mínima (0–9%) às proteínas plasmáticas.',
   E'After nebulization of 2 mg, only ~7% of the dose reaches the systemic circulation (from the lung or GI tract). Minimal (0–9%) plasma protein binding.',
   E'Semivida de eliminação ~1,6 h após administração intravenosa.',
   E'Elimination half-life ~1.6 h after intravenous administration.',
   'Rótulo aprovado DailyMed (Ipratropium Bromide Solution; setID 6b730dd7-4d93-403a-bfd2-fa0efa298b75).',
   'DailyMed approved label (Ipratropium Bromide Solution; setID 6b730dd7-4d93-403a-bfd2-fa0efa298b75).'),
  ('memantina',
   E'Antagonista NMDA de afinidade baixa a moderada: a ativação persistente dos recetores NMDA centrais pelo glutamato contribui para a sintomatologia da doença de Alzheimer; a memantina modula esta excitotoxicidade sem interferir com a transmissão sináptica fisiológica.',
   E'Low to moderate affinity NMDA antagonist: persistent activation of central NMDA receptors by glutamate contributes to Alzheimer symptomatology; memantine modulates this excitotoxicity without interfering with physiological synaptic transmission.',
   E'Antagonismo não competitivo (canal aberto) dos recetores NMDA, com afinidade baixa a moderada, ligando-se preferencialmente aos canais catiónicos operados pelo recetor; sem evidência de prevenção ou abrandamento da neurodegenerescência.',
   E'Uncompetitive (open-channel) antagonism of NMDA receptors, with low to moderate affinity, binding preferentially to the receptor-operated cation channels; no evidence of preventing or slowing neurodegeneration.',
   E'Metabolismo hepático mínimo (sem metabolitos ativos); a excreção é predominantemente renal, inalterada (~50%) e como metabolitos.',
   E'Minimal hepatic metabolism (no active metabolites); excretion is predominantly renal, unchanged (~50%) and as metabolites.',
   E'Biodisponibilidade oral de ~100%; picos plasmáticos em 3–8 horas; a absorção não é afetada pelos alimentos.',
   E'Oral bioavailability of ~100%; plasma peaks at 3–8 hours; absorption is not affected by food.',
   E'Semivida de eliminação de ~60–80 horas (aumenta com a insuficiência renal e, ligeiramente, com a hepática).',
   E'Elimination half-life of ~60–80 hours (increased in renal impairment and slightly in hepatic impairment).',
   'Rótulo aprovado DailyMed (Memantine Hydrochloride Tablet; setID cbfd9d95-f50b-45ff-9857-9f1712c45e56).',
   'DailyMed approved label (Memantine Hydrochloride Tablet; setID cbfd9d95-f50b-45ff-9857-9f1712c45e56).'),
  ('midodrina',
   E'O efeito terapêutico deve-se ao metabolito ativo desglimidodrina, agonista alfa-1 que aumenta o tónus arteriolar e venoso, elevando a pressão arterial em ortostatismo, sentado e em decúbito. Não estimula os recetores beta cardíacos; eleva a PAS ortostática ~15–30 mmHg 1 hora após 10 mg.',
   E'Therapeutic effect is due to the active metabolite desglymidodrine, an alpha-1 agonist that increases arteriolar and venous tone, raising blood pressure standing, sitting and supine. It does not stimulate cardiac beta receptors; raises standing SBP ~15–30 mmHg 1 hour after 10 mg.',
   E'Pró-fármaco: a desglimidodrina ativa os recetores alfa-1-adrenérgicos da vasculatura arteriolar e venosa; difunde pouco através da barreira hematoencefálica, sem efeitos centrais.',
   E'Prodrug: desglymidodrine activates alpha-1-adrenergic receptors of arteriolar and venous vasculature; diffuses poorly across the blood-brain barrier, with no central effects.',
   E'Metabolizado por deglicinação em desglimidodrina em muitos tecidos; ambos os compostos são metabolizados em parte no fígado; não são substratos da monoamina oxidase. A eliminação renal da midodrina é insignificante; a clearance renal da desglimidodrina é ~385 mL/min (~80% por secreção tubular ativa).',
   E'Metabolized by deglycination to desglymidodrine in many tissues; both compounds are partly metabolized in the liver; not substrates of monoamine oxidase. Renal elimination of midodrine is insignificant; renal clearance of desglymidodrine is ~385 mL/min (~80% by active tubular secretion).',
   E'Rapidamente absorvida: picos da pró-fármaco em ~30 min e do metabolito ativo em 1–2 horas; biodisponibilidade absoluta de 93% (medida como desglimidodrina); sem ligação proteica significativa.',
   E'Rapidly absorbed: prodrug peaks at ~30 min and active metabolite at 1–2 hours; absolute bioavailability of 93% (measured as desglymidodrine); no significant protein binding.',
   E'Semivida da midodrina ~25 min; semivida da desglimidodrina ~3–4 horas.',
   E'Half-life of midodrine ~25 min; half-life of desglymidodrine ~3–4 hours.',
   'Rótulo aprovado DailyMed (Midodrine Hydrochloride Tablet, Northstar Rx; setID 79b712a3-be12-4ea6-ac42-742826685ae5).',
   'DailyMed approved label (Midodrine Hydrochloride Tablet, Northstar Rx; setID 79b712a3-be12-4ea6-ac42-742826685ae5).'),
  ('montelukast',
   E'Antagonista oral seletivo do recetor CysLT1: bloqueia os efeitos dos leucotrienos cisteinílicos (LTC4, LTD4, LTE4) nas vias aéreas e na mucosa nasal, reduzindo o edema, a contração do músculo liso e a atividade inflamatória associada à asma e à rinite alérgica.',
   E'Oral selective CysLT1 receptor antagonist: blocks the effects of cysteinyl leukotrienes (LTC4, LTD4, LTE4) in the airways and nasal mucosa, reducing edema, smooth-muscle contraction and inflammatory activity associated with asthma and allergic rhinitis.',
   E'Ligação de alta afinidade e seletividade ao recetor CysLT1 dos leucotrienos cisteinílicos (em preferência a outros recetores farmacologicamente importantes).',
   E'High-affinity, selective binding to the CysLT1 receptor of cysteinyl leukotrienes (in preference to other pharmacologically important receptors).',
   E'Extensamente metabolizado (CYP3A4, CYP2C8 e CYP2C9); os metabolitos são excretados quase exclusivamente na bílis.',
   E'Extensively metabolized (CYP3A4, CYP2C8 and CYP2C9); metabolites are excreted almost exclusively in bile.',
   E'Biodisponibilidade oral de 64% após comprimido de 10 mg; picos plasmáticos em 3–4 horas; ligação às proteínas plasmáticas > 99%.',
   E'Oral bioavailability of 64% after a 10 mg tablet; plasma peaks at 3–4 hours; plasma protein binding > 99%.',
   E'Semivida de 2,7–5,5 horas (em adultos saudáveis).',
   E'Half-life of 2.7–5.5 hours (in healthy adults).',
   'Rótulo aprovado DailyMed (Montelukast Tablet; setID 583a9499-97f0-2ebf-e063-6394a90a35af).',
   'DailyMed approved label (Montelukast Tablet; setID 583a9499-97f0-2ebf-e063-6394a90a35af).'),
  ('nistatina',
   E'Antifúngico poliénico com efeito fungistático e fungicida contra leveduras e fungos semelhantes a leveduras: liga-se aos esteróis da membrana celular das espécies de Candida suscetíveis, alterando a permeabilidade e permitindo a fuga de componentes intracelulares.',
   E'Polyene antifungal with fungistatic and fungicidal effect against yeasts and yeast-like fungi: binds to sterols in the cell membrane of susceptible Candida species, altering permeability and allowing leakage of intracellular components.',
   E'Ligação aos esteróis (ergosterol) da membrana celular fúngica, com alteração da permeabilidade e lise celular; sem atividade apreciável contra bactérias, protozoários ou vírus.',
   E'Binding to fungal membrane sterols (ergosterol), altering permeability and causing cell lysis; no appreciable activity against bacteria, protozoa or viruses.',
   E'Metabolismo hepático mínimo (o fármaco atua localmente no lúmen gastrointestinal).',
   E'Minimal hepatic metabolism (acts locally in the GI lumen).',
   E'Absorção gastrointestinal insignificante: a maior parte da dose oral é eliminada inalterada nas fezes; podem ocorrer concentrações plasmáticas significativas em doentes com insuficiência renal.',
   E'Insignificant GI absorption: most of the oral dose is eliminated unchanged in feces; significant plasma concentrations may occur in patients with renal insufficiency.',
   E'Não aplicável por via oral (ausência de absorção sistémica significativa).',
   E'Not applicable orally (no significant systemic absorption).',
   'Rótulo aprovado DailyMed (Nystatin Tablet; setID 197e3046-3e58-4246-b260-f3995dce41a1).',
   'DailyMed approved label (Nystatin Tablet; setID 197e3046-3e58-4246-b260-f3995dce41a1).'),
-- ---------------------------------------------------------------------
-- Farmacologia — F5 (ondansetron, piperacilina-tazobactam, pirazinamida, poractant alfa, primaquina)
-- ---------------------------------------------------------------------
  ('ondansetron',
   E'Antagonista seletivo dos recetores 5-HT3, presentes perifericamente nos terminais do vago e centralmente na zona de gatilho dos quimiorrecetores da área postrema; bloqueia o reflexo do vómito desencadeado pela serotonina libertada pelas células enterocromafins após quimioterapia ou radioterapia.',
   E'Selective 5-HT3 receptor antagonist, with receptors present peripherally on vagal nerve terminals and centrally in the chemoreceptor trigger zone of the area postrema; blocks the vomiting reflex triggered by serotonin released from enterochromaffin cells after chemotherapy or radiotherapy.',
   E'Bloqueio seletivo dos recetores 5-HT3 (não é antagonista dos recetores de dopamina), inibindo a estimulação vagal aferente e o gatilho central do vómito.',
   E'Selective blockade of 5-HT3 receptors (not a dopamine receptor antagonist), inhibiting vagal afferent stimulation and the central vomiting trigger.',
   E'Extensamente metabolizado no fígado: hidroxilação do anel indólico seguida de conjugação com glucuronido ou sulfato; substrato de CYP1A2, CYP2D6 e CYP3A4 (CYP3A4 predominante no turnover total). ~5% da dose é recuperada inalterada na urina.',
   E'Extensively metabolized in the liver: hydroxylation of the indole ring followed by glucuronide or sulfate conjugation; substrate of CYP1A2, CYP2D6 and CYP3A4 (CYP3A4 predominant in overall turnover). ~5% of the dose is recovered unchanged in urine.',
   E'Biodisponibilidade oral média de ~56% (comprimido de 8 mg), com algum efeito de primeira passagem; a biodisponibilidade aumenta ligeiramente com alimentos. Ligação às proteínas plasmáticas de 70–76%.',
   E'Mean oral bioavailability of ~56% (8 mg tablet), with some first-pass effect; bioavailability slightly enhanced by food. Plasma protein binding 70–76%.',
   E'Semivida média de ~5,7 h em voluntários saudáveis; aumenta para ~11,6 h na insuficiência hepática ligeira a moderada e ~20 h na grave.',
   E'Mean half-life of ~5.7 h in healthy subjects; increased to ~11.6 h in mild-to-moderate hepatic impairment and ~20 h in severe impairment.',
   'Rótulo aprovado DailyMed (Ondansetron Hydrochloride Tablet; setID 14276805-4e99-4bbe-ad76-ffc06eddb38a).',
   'DailyMed approved label (Ondansetron Hydrochloride Tablet; setID 14276805-4e99-4bbe-ad76-ffc06eddb38a).'),
  ('piperacilina_tazobactam',
   E'O parâmetro farmacodinâmico mais preditivo de eficácia clínica e microbiológica é o tempo acima da CMI. A associação cobre Gram-positivos e Gram-negativos, incluindo microrganismos produtores de beta-lactamase e Pseudomonas aeruginosa.',
   E'The pharmacodynamic parameter most predictive of clinical and microbiological efficacy is time above the MIC. The combination covers Gram-positives and Gram-negatives, including beta-lactamase-producing organisms and Pseudomonas aeruginosa.',
   E'A piperacilina inibe a síntese da parede celular bacteriana; o tazobactam protege a piperacilina da hidrólise pelas beta-lactamases (inibidor suicida de beta-lactamases).',
   E'Piperacillin inhibits bacterial cell-wall synthesis; tazobactam protects piperacillin from beta-lactamase hydrolysis (suicide beta-lactamase inhibitor).',
   E'A piperacilina é parcialmente metabolizada (desetilpiperacilina, inativa); o tazobactam é metabolizado num metabolito inativo. Ambos são excretados principalmente por via renal, inalterados.',
   E'Piperacillin is partially metabolized (inactive desethylpiperacillin); tazobactam is metabolized to an inactive metabolite. Both are excreted mainly unchanged by the renal route.',
   E'Administração exclusivamente IV; após dose IV, a distribuição é ampla (V ~15–17 L), com boa penetração tecidular.',
   E'Exclusively IV administration; after IV dosing, distribution is wide (V ~15–17 L), with good tissue penetration.',
   E'Semividas de ~0,7–0,9 h para a piperacilina e ~0,7–0,8 h para o tazobactam; prolongam-se na insuficiência renal.',
   E'Half-lives of ~0.7–0.9 h for piperacillin and ~0.7–0.8 h for tazobactam; prolonged in renal impairment.',
   'Rótulo aprovado DailyMed (Piperacillin and Tazobactam Injection; setID 4d3f4b69-b0b9-494f-9cda-4537fa420d47).',
   'DailyMed approved label (Piperacillin and Tazobactam Injection; setID 4d3f4b69-b0b9-494f-9cda-4537fa420d47).'),
  ('pirazinamida',
   E'Atividade bactericida contra M. tuberculosis, especialmente contra os bacilos intracelulares em meio ácido (fagolisossomas); pode ser bacteriostático ou bactericida consoante a concentração. O ácido pirazinoico ativo permite encurtar a duração do esquema inicial da tuberculose.',
   E'Bactericidal activity against M. tuberculosis, especially against intracellular bacilli in acid medium (phagolysosomes); bacteriostatic or bactericidal depending on concentration. Active pyrazinoic acid allows shortening of the initial tuberculosis regimen.',
   E'Hidrólise hepática no metabolito ativo ácido pirazinoico, que inibe a síntese de ácidos gordos do bacilo em meio ácido; o ácido pirazinoico é hidroxilado no principal produto excretado, o ácido 5-hidroxipirazinoico.',
   E'Hepatic hydrolysis to the active metabolite pyrazinoic acid, which inhibits bacillary fatty-acid synthesis in acid medium; pyrazinoic acid is hydroxylated to the main excretory product, 5-hydroxypyrazinoic acid.',
   E'Hidrolisado no fígado a ácido pirazinoico (metabolito ativo); ~70% da dose oral é excretada na urina, principalmente por filtração glomerular, em 24 horas.',
   E'Hydrolyzed in the liver to pyrazinoic acid (active metabolite); ~70% of an oral dose is excreted in urine, mainly by glomerular filtration, within 24 hours.',
   E'Bem absorvido no trato gastrointestinal; picos plasmáticos em 2 horas (30–50 mcg/mL com doses de 20–25 mg/kg); distribuição ampla (fígado, pulmões, LCR — concentração no LCR ~igual à plasmática com meninges inflamadas). Ligação proteica ~10%.',
   E'Well absorbed from the GI tract; plasma peaks within 2 hours (30–50 mcg/mL with doses of 20–25 mg/kg); wide distribution (liver, lungs, CSF — CSF concentration ~equal to plasma with inflamed meninges). Protein binding ~10%.',
   E'Semivida de 9–10 horas em doentes com função renal e hepática normais; prolonga-se na insuficiência renal ou hepática.',
   E'Half-life of 9–10 hours in patients with normal renal and hepatic function; prolonged in renal or hepatic impairment.',
   'Rótulo aprovado DailyMed (Pyrazinamide Tablet, ANI Pharmaceuticals; setID 262d8829-728c-48db-b89b-88d13b87e684).',
   'DailyMed approved label (Pyrazinamide Tablet, ANI Pharmaceuticals; setID 262d8829-728c-48db-b89b-88d13b87e684).'),
  ('poractant_alfa',
   E'O surfactante pulmonar endógeno reduz a tensão superficial na interface ar-líquido dos alvéolos durante a ventilação e estabiliza os alvéolos contra o colapso; o CUROSURF compensa a deficiência de surfactante dos prematuros e restaura a atividade de superfície pulmonar. In vitro, reduz a tensão superficial mínima para ≤ 4 mN/m.',
   E'Endogenous pulmonary surfactant reduces surface tension at the air-liquid interface of the alveoli during ventilation and stabilizes alveoli against collapse; CUROSURF compensates the surfactant deficiency of preterm infants and restores pulmonary surface activity. In vitro, it lowers minimum surface tension to ≤ 4 mN/m.',
   E'Restauração da atividade de superfície alveolar por administração intratraqueal direta de fosfolípidos e proteínas surfactantes (SP-B, SP-C) de origem porcina, melhorando a oxigenação e a complacência pulmonar.',
   E'Restoration of alveolar surface activity by direct intratracheal administration of porcine phospholipids and surfactant proteins (SP-B, SP-C), improving oxygenation and lung compliance.',
   E'Administrado diretamente no pulmão, onde ocorrem os efeitos biofísicos na superfície alveolar; não há estudos farmacocinéticos humanos que caracterizem a absorção, biotransformação ou eliminação.',
   E'Administered directly to the lung, where biophysical effects occur at the alveolar surface; no human pharmacokinetic studies characterize absorption, biotransformation or elimination.',
   E'Administração intratraqueal (o fármaco atua localmente no alvéolo; sem absorção sistémica relevante).',
   E'Intratracheal administration (acts locally at the alveolus; no relevant systemic absorption).',
   E'Não aplicável — sem estudos farmacocinéticos humanos; ação local no pulmão.',
   E'Not applicable — no human pharmacokinetic studies; local action in the lung.',
   'Rótulo aprovado DailyMed (CUROSURF, Chiesi USA; setID 99bef307-00bd-4379-9f45-ede1380e74d4).',
   'DailyMed approved label (CUROSURF, Chiesi USA; setID 99bef307-00bd-4379-9f45-ede1380e74d4).'),
  ('primaquina',
   E'Antimalárico 8-aminoquinoleína ativo contra os hipnozoítos hepáticos do P. vivax e os estádios exoeritrocíticos, prevenindo as recaídas; também ativo contra os gametócitos do P. falciparum. A atividade depende provavelmente de metabolitos hidroxilados gerados intra-hepaticamente por CYP2D6.',
   E'8-aminoquinoline antimalarial active against liver hypnozoites of P. vivax and exoerythrocytic stages, preventing relapses; also active against gametocytes of P. falciparum. Activity probably depends on hydroxylated metabolites generated intrahepatically by CYP2D6.',
   E'Inibição do sistema mitocondrial dos parasitas dormentes e stress oxidativo através de metabolitos reativos nas células infetadas; os metabolitos ativos dependem de CYP2D6.',
   E'Inhibition of the mitochondrial system of dormant parasites and oxidative stress through reactive metabolites in infected cells; active metabolites depend on CYP2D6.',
   E'Metabolizado extensamente (incluindo carboxiprimaquina, metabolito circulante principal inativo); excreção renal e metabólica; os metabolitos dependem de polimorfismos de CYP2D6.',
   E'Extensively metabolized (including carboxyprimaquine, the main circulating inactive metabolite); renal and metabolic excretion; metabolites depend on CYP2D6 polymorphisms.',
   E'Bem absorvido por via oral; a Cmax e a AUC aumentam aproximadamente de forma proporcional à dose entre 15 e 45 mg.',
   E'Well absorbed orally; Cmax and AUC increase approximately dose-proportionally over 15 to 45 mg.',
   E'Semivida de eliminação de ~4–6 horas (mais curta em metabolizadores rápidos de CYP2D6; aumentada em metabolizadores lentos, com maior risco de hemólise e níveis elevados).',
   E'Elimination half-life of ~4–6 hours (shorter in CYP2D6 rapid metabolizers; increased in poor metabolizers, with higher hemolysis risk and elevated levels).',
   'Rótulo aprovado DailyMed (Primaquine Phosphate Tablet; setID 3f16166d-678e-51aa-e054-00144ff88e88).',
   'DailyMed approved label (Primaquine Phosphate Tablet; setID 3f16166d-678e-51aa-e054-00144ff88e88).'),
-- ---------------------------------------------------------------------
-- Farmacologia — F6 (propafenona, salmeterol, tafenoquina, tiotropio, zidovudina)
-- ---------------------------------------------------------------------
  ('propafenona',
   E'Antiarrítmico de classe IC: reduz a velocidade de subida (fase 0) do potencial de ação monofásico, prolonga o período refratário efetivo, aumenta o limiar de excitabilidade diastólica e reduz a automaticidade espontânea; atividade bloqueadora beta ~1/40 da do propranolol por mg.',
   E'Class 1C antiarrhythmic: reduces the upstroke velocity (Phase 0) of the monophasic action potential, prolongs the effective refractory period, increases the diastolic excitability threshold and reduces spontaneous automaticity; beta-blocking activity ~1/40 that of propranolol per mg.',
   E'Bloqueio dos canais de sódio rápidos do miocárdio (ação estabilizadora de membrana) com anestesia local; a redução do influxo rápido de sódio nas fibras de Purkinje e do miocárdio reduz a condução e a excitabilidade.',
   E'Blockade of fast myocardial sodium channels (membrane-stabilizing action) with local anesthetic effect; reduced fast sodium inward current in Purkinje and myocardial fibers decreases conduction and excitability.',
   E'Extenso metabolismo de primeira passagem (saturável): em > 90% dos doentes (metabolizadores extensos de CYP2D6) forma 5-hidroxipropafenona (ativa) e N-despropilpropafenona (CYP3A4/CYP1A2); nos metabolizadores lentos a semivida é maior e os níveis 1,5–5x superiores.',
   E'Extensive saturable first-pass metabolism: in > 90% of patients (CYP2D6 extensive metabolizers) it forms 5-hydroxypropafenone (active) and N-depropylpropafenone (CYP3A4/CYP1A2); in poor metabolizers half-life is longer and levels 1.5–5x higher.',
   E'Quase completamente absorvida por via oral, com picos plasmáticos ~3,5 h; biodisponibilidade absoluta dose-dependente (3,4% com 150 mg; 10,6% com 300 mg; até 21,4% com solução); ligação proteica > 95%.',
   E'Almost completely absorbed orally, with plasma peaks ~3.5 h; dose-dependent absolute bioavailability (3.4% with 150 mg; 10.6% with 300 mg; up to 21.4% with solution); protein binding > 95%.',
   E'Semivida de eliminação de 2–10 h nos metabolizadores extensos e de 10–32 h nos metabolizadores lentos de CYP2D6.',
   E'Elimination half-life of 2–10 h in CYP2D6 extensive metabolizers and 10–32 h in poor metabolizers.',
   'Rótulo aprovado DailyMed (Propafenone Hydrochloride Extended-Release Capsule; setID 2ecd6452-ccc3-493f-9a4a-69f0fbf67a42).',
   'DailyMed approved label (Propafenone Hydrochloride Extended-Release Capsule; setID 2ecd6452-ccc3-493f-9a4a-69f0fbf67a42).'),
  ('salmeterol',
   E'Beta-2-agonista de ação prolongada: o estímulo da adenilciclase intracelular aumenta o AMP cíclico, relaxando o músculo liso brônquico e inibindo a libertação de mediadores de hipersensibilidade imediata das células, especialmente mastócitos. A broncodilatação dura ≥ 12 horas.',
   E'Long-acting beta-2 agonist: stimulation of intracellular adenyl cyclase increases cyclic AMP, relaxing bronchial smooth muscle and inhibiting release of immediate-hypersensitivity mediators from cells, especially mast cells. Bronchodilation lasts ≥ 12 hours.',
   E'Agonismo seletivo dos recetores beta-2-adrenérgicos (≥ 50x mais seletivo que o albuterol in vitro), com efeito broncodilatador prolongado; a presença de recetores beta-2 no coração (10–50% do total) explica possíveis efeitos cardíacos.',
   E'Selective agonism of beta-2-adrenergic receptors (≥ 50x more selective than albuterol in vitro), with prolonged bronchodilator effect; beta-2 receptors in the heart (10–50% of total) explain possible cardiac effects.',
   E'Extensamente hidroxilado (alifático) por CYP3A4; os metabolitos são excretados predominantemente nas fezes.',
   E'Extensively hydroxylated (aliphatic) by CYP3A4; metabolites are excreted predominantly in feces.',
   E'Após inalação, a maior parte da dose é deglutida; os níveis plasmáticos são muito baixos (pico médio de 167 pg/mL aos 20 min, sem acumulação com doses repetidas); a fração inalada atua localmente.',
   E'After inhalation, most of the dose is swallowed; plasma levels are very low (mean peak of 167 pg/mL at 20 min, no accumulation with repeated doses); the inhaled fraction acts locally.',
   E'Semivida de eliminação ~5,5 h (a porção deglutida tem semivida de ~11 dias devido à absorção lenta, mas a exposição sistémica é mínima).',
   E'Elimination half-life ~5.5 h (the swallowed portion has a half-life of ~11 days due to slow absorption, but systemic exposure is minimal).',
   'Rótulo aprovado DailyMed (SEREVENT DISKUS, salmeterol; setID 1349a04c-2024-42b9-b81d-a7d995716ade).',
   'DailyMed approved label (SEREVENT DISKUS, salmeterol; setID 1349a04c-2024-42b9-b81d-a7d995716ade).'),
  ('tafenoquina',
   E'Antimalárico 8-aminoquinoleína com atividade contra os hipnozoítos hepáticos do P. vivax; não prolonga o intervalo QTc de forma clinicamente relevante mesmo em dose cumulativa de 1200 mg (4x a dose máxima recomendada).',
   E'8-aminoquinoline antimalarial active against liver hypnozoites of P. vivax; does not prolong the QTc interval to a clinically relevant extent even at a cumulative dose of 1,200 mg (4x the maximum recommended dose).',
   E'Mecanismo semelhante ao das 8-aminoquinoleínas: inibição da função mitocondrial e stress oxidativo nos estádios hepáticos dormentes do parasita, prevenindo a recaída.',
   E'Mechanism similar to other 8-aminoquinolines: inhibition of mitochondrial function and oxidative stress in dormant liver stages of the parasite, preventing relapse.',
   E'Extensamente metabolizada; a eliminação é lenta (semivida longa), permitindo dose única.',
   E'Extensively metabolized; elimination is slow (long half-life), allowing single-dose administration.',
   E'Concentrações plasmáticas máximas geralmente 12–15 horas após administração oral; os alimentos aumentam a AUC plasmática.',
   E'Maximum plasma concentrations generally 12–15 hours after oral administration; food increases plasma AUC.',
   E'Semivida de eliminação ~15 dias.',
   E'Elimination half-life of ~15 days.',
   'Rótulo aprovado DailyMed (KRINTAFEL, tafenoquina succinato; setID 5cf989d5-36f5-4561-a30b-9fcb9deb6b6a).',
   'DailyMed approved label (KRINTAFEL, tafenoquine succinate; setID 5cf989d5-36f5-4561-a30b-9fcb9deb6b6a).'),
  ('tiotropio',
   E'Antimuscarínico de ação prolongada: o bloqueio dos recetores M3 do músculo liso das vias aéreas produz broncodilatação sustentada (> 24 horas); a prevenção da broncoconstrição induzida por metacolina é dose-dependente e dura mais de 24 horas.',
   E'Long-acting antimuscarinic: blockade of M3 receptors of airway smooth muscle produces sustained bronchodilation (> 24 hours); prevention of methacholine-induced bronchoconstriction is dose-dependent and lasts longer than 24 hours.',
   E'Antagonismo competitivo e reversível dos recetores muscarínicos M1–M5, com efeito predominante via M3 no músculo liso brônquico; o efeito é predominantemente local, no local de inalação.',
   E'Competitive, reversible antagonism of M1–M5 muscarinic receptors, with predominant effect via M3 on bronchial smooth muscle; the effect is predominantly site-specific, at the site of inhalation.',
   E'Metabolismo hepático mínimo (éster não enzimaticamente clivado); a eliminação é predominantemente renal (inalterado) e fecal.',
   E'Minimal hepatic metabolism (non-enzymatic ester cleavage); elimination is predominantly renal (unchanged) and fecal.',
   E'Biodisponibilidade sistémica de 2–3% após inalação (a fração inalada atua localmente); a absorção oral da fração deglutida é mínima.',
   E'Systemic bioavailability of 2–3% after inhalation (the inhaled fraction acts locally); oral absorption of the swallowed fraction is minimal.',
   E'Semivida efetiva de 25 horas (DPOC) e 44 horas (asma) após inalação uma vez por dia.',
   E'Effective half-life of 25 hours (COPD) and 44 hours (asthma) after once-daily inhalation.',
   'Rótulo aprovado DailyMed (SPIRIVA RESPIMAT, Boehringer Ingelheim; setID 7b656b14-fcaa-2741-f6f0-e0be48971c02).',
   'DailyMed approved label (SPIRIVA RESPIMAT, Boehringer Ingelheim; setID 7b656b14-fcaa-2741-f6f0-e0be48971c02).'),
  ('zidovudina',
   E'INTI que inibe a transcriptase reversa do HIV-1, interrompendo a síntese do DNA pró-viral; a fosforilação intracelular em trifosfato de zidovudina (metabolito ativo) compete com a timidina endógena.',
   E'NRTI that inhibits HIV-1 reverse transcriptase, interrupting proviral DNA synthesis; intracellular phosphorylation to zidovudine triphosphate (active metabolite) competes with endogenous thymidine.',
   E'Inibição competitiva da transcriptase reversa viral pelo trifosfato de zidovudina e terminação da cadeia de DNA pró-viral; a toxicidade hematológica e mitocondrial relaciona-se com o metabolito AMT e a inibição da DNA polimerase gama.',
   E'Competitive inhibition of viral reverse transcriptase by zidovudine triphosphate and proviral DNA chain termination; hematologic and mitochondrial toxicity relate to the AMT metabolite and gamma DNA polymerase inhibition.',
   E'Extensamente metabolizado no fígado (principalmente glucuronidação em GZDV inativo; formação do metabolito AMT); a excreção é renal, principalmente como metabolito glucuronido.',
   E'Extensively metabolized in the liver (mainly glucuronidation to inactive GZDV; formation of the AMT metabolite); excretion is renal, mainly as the glucuronide metabolite.',
   E'Rapidamente absorvida e extensamente distribuída por via oral (picos séricos em 0,5–1,5 h); biodisponibilidade oral média de 64% (±10); penetra no LCR (rácio LCR/plasma ~0,6).',
   E'Rapidly absorbed and extensively distributed orally (serum peaks at 0.5–1.5 h); mean oral bioavailability of 64% (±10); penetrates CSF (CSF/plasma ratio ~0.6).',
   E'Semivida plasmática ~1 h em adultos (semivida de ~13 h nos recém-nascidos expostos in utero).',
   E'Plasma half-life ~1 h in adults (half-life of ~13 h in neonates exposed in utero).',
   'Rótulo aprovado DailyMed (RETROVIR, zidovudina; setID e816e8f5-1e50-4f49-8bea-92da0121d26e).',
   'DailyMed approved label (RETROVIR, zidovudine; setID e816e8f5-1e50-4f49-8bea-92da0121d26e)')
) AS v(slug, pharmacodynamics_pt, pharmacodynamics_en, mechanism_pt, mechanism_en,
        metabolism_pt, metabolism_en, absorption_pt, absorption_en,
        half_life_pt, half_life_en, source_pt, source_en)
JOIN public.drugs d ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;

